package com.codex.annals;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class CodexAnnalsPluginRunner
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(CodexAnnalsPlugin.class);
		RuneLite.main(args);
	}
}

package com.codex.annals;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(CodexAnnalsConfig.GROUP)
public interface CodexAnnalsConfig extends Config
{
	String GROUP = "codexannals";

	@ConfigSection(
		name = "Annals",
		description = "What the annals write down",
		position = 0
	)
	String annals = "annals";

	@ConfigSection(
		name = "Display",
		description = "What Codex Annals shows in the game and on the card",
		position = 1
	)
	String display = "display";

	@ConfigItem(
		keyName = "everyLevel",
		name = "Every level",
		description = "Write down every level gained; turn off to keep only every tenth level and the 99s",
		position = 0,
		section = annals
	)
	default boolean everyLevel()
	{
		return true;
	}

	@ConfigItem(
		keyName = "notableDrop",
		name = "Notable drop value",
		description = "A single drop worth at least this many coins is written into the annals",
		position = 1,
		section = annals
	)
	default int notableDrop()
	{
		return 1_000_000;
	}

	@ConfigItem(
		keyName = "chatLine",
		name = "Announce milestones",
		description = "Put a line in the chat box when a 99, a pet, a first kill or another milestone is written down",
		position = 0,
		section = display
	)
	default boolean chatLine()
	{
		return true;
	}

	@ConfigItem(
		keyName = "nameOnCard",
		name = "Name on card",
		description = "Write your character's name on the Year in Gielinor card",
		position = 1,
		section = display
	)
	default boolean nameOnCard()
	{
		return true;
	}
}

package com.codex.annals;

import com.codex.annals.core.Annals;
import com.codex.annals.core.Baseline;
import com.codex.annals.core.ChatParser;
import com.codex.annals.core.Entry;
import com.codex.annals.ui.AnnalsPanel;
import com.codex.annals.ui.CardActions;
import com.codex.annals.ui.Icons;
import com.codex.annals.ui.ItemIcons;
import com.codex.annals.ui.Sigil;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.inject.Provides;
import java.awt.Toolkit;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.OutputStream;
import java.time.ZoneId;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Deque;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.Filepath;
import net.runelite.client.util.Text;
import net.runelite.http.api.loottracker.LootRecordType;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
	name = "Codex Annals",
	description = "A lifetime timeline of your account, every level, quest, diary, log slot, pet and first kill, and a yearly Year in Gielinor card to share",
	tags = {"timeline", "history", "annals", "year", "recap", "milestones", "levels", "quests", "collection", "card", "share", "codex"}
)
public class CodexAnnalsPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(CodexAnnalsPlugin.class);
	private static final String ANNALS_KEY = "annals";
	/** A game tick, the time each logged-in tick stands for. */
	private static final long TICK_MS = 600;
	/** Ticks between panel refreshes when only the clock moved, about half a minute. */
	private static final int REFRESH_TICKS = 50;
	/** Ticks between saves while something changed, about a minute. */
	private static final int SAVE_TICKS = 100;
	/** How long a loot or kill count stays fresh enough to name what a message was about. */
	private static final long RECENT_MS = 10_000;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private SkillIconManager skillIconManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private Gson gson;

	@Inject
	private CodexAnnalsConfig config;

	private AnnalsPanel panel;
	private NavigationButton navButton;

	private String profile;
	private Annals annals = new Annals();
	private boolean live;
	private boolean pendingBegin;
	private boolean dirty;
	private boolean unsaved;
	private int ticks;
	private String recentKill;
	private long recentKillAt;
	private final Deque<RecentItem> recentLoot = new ArrayDeque<>();

	/** An item seen in loot a moment ago, to give a collection log entry its picture. */
	private static final class RecentItem
	{
		final String name;
		final int id;
		final long at;

		RecentItem(String name, int id, long at)
		{
			this.name = name;
			this.id = id;
			this.at = at;
		}
	}

	@Provides
	CodexAnnalsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CodexAnnalsConfig.class);
	}

	@Override
	protected void startUp()
	{
		ItemIcons items = (itemId, onLoaded) ->
		{
			AsyncBufferedImage image = itemManager.getImage(itemId);
			image.onLoaded(onLoaded);
			return image;
		};
		Icons icons = name ->
		{
			try
			{
				return skillIconManager.getSkillImage(Skill.valueOf(name.toUpperCase()), true);
			}
			catch (IllegalArgumentException e)
			{
				return null;
			}
		};
		panel = new AnnalsPanel(items, icons, new CardActions()
		{
			@Override
			public void save(BufferedImage card, int year)
			{
				saveCard(card, year);
			}

			@Override
			public void copy(BufferedImage card)
			{
				copyCard(card);
			}
		});
		panel.setShowName(config.nameOnCard());
		navButton = NavigationButton.builder()
			.tooltip("Codex Annals")
			.icon(Sigil.icon(16))
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		clientThread.invokeLater(() ->
		{
			loadProfile();
			pendingBegin = client.getGameState() == GameState.LOGGED_IN;
			publish();
		});
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		clientThread.invokeLater(() ->
		{
			save();
			annals = new Annals();
			profile = null;
			live = false;
			pendingBegin = false;
		});
		panel = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGGED_IN)
		{
			if (!live)
			{
				pendingBegin = true;
			}
		}
		else if (state == GameState.LOGIN_SCREEN)
		{
			pendingBegin = false;
			if (live)
			{
				live = false;
				save();
				publish();
			}
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		save();
		live = false;
		loadProfile();
		pendingBegin = client.getGameState() == GameState.LOGGED_IN;
		publish();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CodexAnnalsConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		AnnalsPanel target = panel;
		if (target != null)
		{
			boolean showName = config.nameOnCard();
			SwingUtilities.invokeLater(() -> target.setShowName(showName));
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		long now = System.currentTimeMillis();
		if (pendingBegin)
		{
			tryBegin(now);
		}
		if (!live)
		{
			return;
		}
		annals.tick(now, TICK_MS, ZoneId.systemDefault());
		Player player = client.getLocalPlayer();
		if (player != null)
		{
			written(annals.combat(player.getCombatLevel(), now));
		}
		unsaved = true;
		ticks++;
		if (ticks % SAVE_TICKS == 0)
		{
			save();
		}
		if (dirty || ticks % REFRESH_TICKS == 0)
		{
			publish();
		}
	}

	/** Opens the annals once the account and its stats can be read. */
	private void tryBegin(long now)
	{
		Player player = client.getLocalPlayer();
		if (player == null || player.getName() == null || client.getOverallExperience() <= 0)
		{
			return;
		}
		if (profile == null || !profile.equals(configManager.getRSProfileKey()))
		{
			loadProfile();
			if (profile == null)
			{
				return;
			}
		}
		pendingBegin = false;
		Map<String, Long> xp = new LinkedHashMap<>();
		Map<String, Integer> levels = new LinkedHashMap<>();
		List<String> maxed = new ArrayList<>();
		int total = 0;
		for (Skill skill : Skill.values())
		{
			int level = client.getRealSkillLevel(skill);
			xp.put(skill.getName(), (long) client.getSkillExperience(skill));
			levels.put(skill.getName(), level);
			total += level;
			if (level >= 99)
			{
				maxed.add(skill.getName());
			}
		}
		Baseline baseline = null;
		if (!annals.isBegun())
		{
			// Only read once, the day the annals begin: asking every quest its state runs a script each.
			int done = 0;
			for (Quest quest : Quest.values())
			{
				done += quest.getState(client) == QuestState.FINISHED ? 1 : 0;
			}
			baseline = new Baseline(now, total, client.getOverallExperience(), player.getCombatLevel(),
				client.getVarpValue(VarPlayerID.QP), done, Quest.values().length, maxed);
		}
		int yearsBefore = annals.getYears().size();
		int lastYear = yearsBefore == 0 ? 0 : annals.getYears().get(yearsBefore - 1).getYear();
		written(annals.begin(now, ZoneId.systemDefault(), player.getName(), baseline, xp, levels, player.getCombatLevel()));
		if (yearsBefore > 0 && annals.getYears().size() > yearsBefore && config.chatLine())
		{
			announce("your " + lastYear + " in Gielinor is complete. Its card is waiting in the Annals panel.");
		}
		live = true;
		save();
		dirty = true;
		publish();
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (!live)
		{
			return;
		}
		written(annals.stat(event.getSkill().getName(), event.getXp(), event.getLevel(), System.currentTimeMillis(),
			ZoneId.systemDefault(), config.everyLevel()));
		unsaved = true;
	}

	@Subscribe
	public void onNpcLootReceived(NpcLootReceived event)
	{
		NPC npc = event.getNpc();
		loot(npc == null ? null : npc.getName(), event.getItems());
	}

	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		// Kills arrive through NpcLootReceived on their own, and player kills are left out.
		LootRecordType type = event.getType();
		if (type == LootRecordType.NPC || type == LootRecordType.PLAYER)
		{
			return;
		}
		loot(event.getName(), event.getItems());
	}

	private void loot(String source, Collection<ItemStack> items)
	{
		if (!live)
		{
			return;
		}
		long now = System.currentTimeMillis();
		String from = source == null ? null : Text.removeTags(source);
		if (from != null)
		{
			recentKill = from;
			recentKillAt = now;
		}
		while (!recentLoot.isEmpty() && now - recentLoot.peekFirst().at > RECENT_MS)
		{
			recentLoot.removeFirst();
		}
		for (ItemStack stack : items)
		{
			int id = itemManager.canonicalize(stack.getId());
			ItemComposition item = itemManager.getItemComposition(id);
			String name = item.getName();
			recentLoot.addLast(new RecentItem(name, id, now));
			// A collection log message can come before the loot it was about.
			annals.attachItem(name, id, now - RECENT_MS);
			long value = (long) itemManager.getItemPrice(id) * stack.getQuantity();
			if (value >= config.notableDrop())
			{
				written(annals.drop(name, stack.getQuantity(), id, value, from, now));
			}
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!live || (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM))
		{
			return;
		}
		String message = Text.removeTags(event.getMessage()).replace(' ', ' ').trim();
		long now = System.currentTimeMillis();
		ZoneId zone = ZoneId.systemDefault();
		ChatParser.KillCount kc = ChatParser.killCount(message);
		if (kc != null)
		{
			recentKill = kc.getName();
			recentKillAt = now;
			written(annals.killCount(kc.getName(), kc.getCount(), now, zone));
			return;
		}
		Entry entry = ChatParser.entry(message, now, now - recentKillAt <= RECENT_MS ? recentKill : null);
		if (entry == null)
		{
			return;
		}
		Entry kept = annals.record(entry, now, zone);
		if (kept != null && kept.getKind() == Entry.Kind.COLLECTION)
		{
			for (RecentItem item : recentLoot)
			{
				if (now - item.at <= RECENT_MS && item.name.equalsIgnoreCase(kept.getTitle()))
				{
					annals.attachItem(item.name, item.id, now - RECENT_MS);
				}
			}
		}
		written(kept);
	}

	private void written(List<Entry> entries)
	{
		for (Entry e : entries)
		{
			written(e);
		}
	}

	/** Marks the annals changed and, for the milestones the game does not announce itself, says so in chat. */
	private void written(Entry e)
	{
		if (e == null)
		{
			return;
		}
		dirty = true;
		unsaved = true;
		if (!config.chatLine())
		{
			return;
		}
		switch (e.getKind())
		{
			case MAX:
			case TOTAL:
			case XP:
			case COMBAT:
			case BOSS:
			case DROP:
				announce(e.getTitle() + ", written into your annals.");
				break;
			default:
				break;
		}
	}

	private void announce(String text)
	{
		String line = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT).append("Codex Annals: ")
			.append(ChatColorType.NORMAL).append(text)
			.build();
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(line)
			.build());
	}

	private void loadProfile()
	{
		profile = configManager.getRSProfileKey();
		annals = new Annals();
		recentLoot.clear();
		if (profile == null)
		{
			return;
		}
		try
		{
			String saved = configManager.getRSProfileConfiguration(CodexAnnalsConfig.GROUP, ANNALS_KEY);
			if (saved != null && !saved.isEmpty())
			{
				Annals read = gson.fromJson(saved, Annals.class);
				if (read != null)
				{
					annals = read.repair();
				}
			}
		}
		catch (JsonParseException e)
		{
			log.warn("Could not read the saved annals, starting them afresh", e);
		}
	}

	private void save()
	{
		if (!unsaved || profile == null || !annals.isBegun())
		{
			return;
		}
		unsaved = false;
		configManager.setConfiguration(CodexAnnalsConfig.GROUP, profile, ANNALS_KEY, gson.toJson(annals));
	}

	/** Sends the panel a copy of the annals, so Swing never reads what the client thread is writing. */
	private void publish()
	{
		dirty = false;
		Annals copy = gson.fromJson(gson.toJson(annals), Annals.class).repair();
		Player player = client.getLocalPlayer();
		String name = client.getGameState() == GameState.LOGGED_IN && player != null ? player.getName() : null;
		AnnalsPanel target = panel;
		if (target != null)
		{
			ZoneId zone = ZoneId.systemDefault();
			SwingUtilities.invokeLater(() -> target.update(copy.isBegun() ? copy : null, zone, name));
		}
	}

	/** Asks where to save the card with RuneLite's own file chooser, then writes it there; runs on the Swing thread. */
	private void saveCard(BufferedImage card, int year)
	{
		List<Filepath> chosen = new Filepath.Chooser()
			.setIsSave()
			.setAcceptsFiles()
			.setDialogTitle("Save Year in Gielinor card")
			.addExtensionFilter("PNG image", "png")
			.setDefaultExtension("png")
			.setFileName("Year in Gielinor " + year + ".png")
			.showDialog(panel);
		if (chosen == null || chosen.isEmpty())
		{
			return;
		}
		Filepath target = chosen.get(0);
		executor.execute(() ->
		{
			String note;
			try (OutputStream out = target.openOutputStream())
			{
				ImageIO.write(card, "png", out);
				note = "Saved as " + target.getFileName() + ".";
			}
			catch (IOException e)
			{
				log.warn("Could not save the year card", e);
				note = "The card could not be saved: " + e.getMessage();
			}
			String shown = note;
			AnnalsPanel view = panel;
			if (view != null)
			{
				SwingUtilities.invokeLater(() -> view.cardNote(shown));
			}
		});
	}

	private void copyCard(BufferedImage card)
	{
		String note;
		try
		{
			Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new ImageTransfer(card), null);
			note = "Copied. Paste it anywhere you share pictures.";
		}
		catch (IllegalStateException e)
		{
			note = "The clipboard is busy, try again in a moment.";
		}
		AnnalsPanel target = panel;
		if (target != null)
		{
			target.cardNote(note);
		}
	}
}

package com.codex.annals;

import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.Transferable;
import java.awt.datatransfer.UnsupportedFlavorException;
import java.awt.image.BufferedImage;

/** Hands the card to the system clipboard as a picture. */
final class ImageTransfer implements Transferable
{
	private final BufferedImage image;

	ImageTransfer(BufferedImage image)
	{
		this.image = image;
	}

	@Override
	public DataFlavor[] getTransferDataFlavors()
	{
		return new DataFlavor[]{DataFlavor.imageFlavor};
	}

	@Override
	public boolean isDataFlavorSupported(DataFlavor flavor)
	{
		return DataFlavor.imageFlavor.equals(flavor);
	}

	@Override
	public Object getTransferData(DataFlavor flavor) throws UnsupportedFlavorException
	{
		if (!isDataFlavorSupported(flavor))
		{
			throw new UnsupportedFlavorException(flavor);
		}
		return image;
	}
}

package com.codex.annals.core;

import java.time.Instant;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * The account's whole history as Codex Annals keeps it: every entry since the annals began,
 * a ledger per calendar year, and the last reading of every skill and kill count. It is plain
 * data so it saves as one blob, and every change goes through the methods here.
 */
public class Annals
{
	/** More than this and the least telling old entries make room; ordinary levels go first. */
	static final int MAX_ENTRIES = 2000;
	private static final int[] KC_MILESTONES = {50, 100, 250, 500, 1000, 2000, 5000, 10000};
	private static final long[] SKILL_XP = {50_000_000L, 100_000_000L, 200_000_000L};
	private static final long MAX_XP = 200_000_000L;
	/** How close a drop and its collection log message must be to count as one. */
	private static final long MERGE_MS = 30_000;

	long begunAt;
	String player;
	Baseline baseline;
	/** Oldest first. */
	List<Entry> entries = new ArrayList<>();
	/** Oldest first. */
	List<Year> years = new ArrayList<>();
	Map<String, Integer> kc = new LinkedHashMap<>();
	Map<String, Integer> levels = new LinkedHashMap<>();
	Map<String, Long> xp = new LinkedHashMap<>();
	int combat;

	public boolean isBegun()
	{
		return begunAt > 0;
	}

	public long getBegunAt()
	{
		return begunAt;
	}

	public String getPlayer()
	{
		return player;
	}

	public Baseline getBaseline()
	{
		return baseline;
	}

	/** Every entry, oldest first. Read only. */
	public List<Entry> getEntries()
	{
		return Collections.unmodifiableList(entries);
	}

	/** Every year kept, oldest first. Read only. */
	public List<Year> getYears()
	{
		return Collections.unmodifiableList(years);
	}

	public Year getYear(int year)
	{
		for (Year y : years)
		{
			if (y.year == year)
			{
				return y;
			}
		}
		return null;
	}

	public Map<String, Integer> getKillCounts()
	{
		return Collections.unmodifiableMap(kc);
	}

	/** Makes sure every field exists after Gson has read an older or damaged save. */
	public Annals repair()
	{
		if (entries == null)
		{
			entries = new ArrayList<>();
		}
		entries.removeIf(e -> e == null);
		if (years == null)
		{
			years = new ArrayList<>();
		}
		years.removeIf(y -> y == null);
		for (Year y : years)
		{
			y.repair();
		}
		if (kc == null)
		{
			kc = new LinkedHashMap<>();
		}
		if (levels == null)
		{
			levels = new LinkedHashMap<>();
		}
		if (xp == null)
		{
			xp = new LinkedHashMap<>();
		}
		return this;
	}

	/**
	 * Picks up the account once its stats can be read. The first time, the annals begin and the
	 * baseline is written down; afterwards it only takes the current stats in quietly, since
	 * levels gained with the plugin off have no day to put them on.
	 *
	 * @return the entries written, at most the opening one
	 */
	public List<Entry> begin(long now, ZoneId zone, String player, Baseline start, Map<String, Long> xpNow, Map<String, Integer> levelsNow, int combatNow)
	{
		List<Entry> written = new ArrayList<>();
		this.player = player;
		xp.putAll(xpNow);
		levels.putAll(levelsNow);
		combat = combatNow;
		Year year = year(now, zone);
		for (Map.Entry<String, Long> e : xpNow.entrySet())
		{
			year.startXp.putIfAbsent(e.getKey(), e.getValue());
			year.endXp.put(e.getKey(), e.getValue());
		}
		for (Map.Entry<String, Integer> e : levelsNow.entrySet())
		{
			year.startLevel.putIfAbsent(e.getKey(), e.getValue());
			year.endLevel.put(e.getKey(), e.getValue());
		}
		if (!isBegun())
		{
			begunAt = now;
			baseline = start;
			String detail = "Total level " + number(start.getTotalLevel()) + ", combat " + start.getCombat();
			if (start.getQuestPoints() > 0)
			{
				detail += ", " + start.getQuestPoints() + " quest points";
			}
			written.add(add(new Entry(Entry.Kind.BEGIN, now, "The annals begin", detail)));
		}
		return written;
	}

	/** A skill's experience or level changed. */
	public List<Entry> stat(String skill, long xpNow, int levelNow, long now, ZoneId zone, boolean everyLevel)
	{
		List<Entry> written = new ArrayList<>();
		if (!isBegun())
		{
			return written;
		}
		Year year = year(now, zone);
		Long xpBefore = xp.get(skill);
		Integer levelBefore = levels.get(skill);
		year.startXp.putIfAbsent(skill, xpBefore == null ? xpNow : xpBefore);
		year.startLevel.putIfAbsent(skill, levelBefore == null ? levelNow : levelBefore);
		year.endXp.put(skill, xpNow);
		year.endLevel.put(skill, levelNow);
		xp.put(skill, xpNow);
		levels.put(skill, levelNow);
		if (xpBefore == null || levelBefore == null)
		{
			// A skill seen for the first time, such as one added to the game: nothing to compare with.
			return written;
		}

		int totalBefore = totalLevel() - levelNow + levelBefore;
		if (levelNow > levelBefore)
		{
			if (levelNow >= 99 && levelBefore < 99)
			{
				int maxed = 0;
				for (int level : levels.values())
				{
					maxed += level >= 99 ? 1 : 0;
				}
				String detail = maxed == 1 ? "Your first 99" : maxed == levels.size() ? "Every skill at 99" : "99 number " + maxed;
				written.add(add(new Entry(Entry.Kind.MAX, now, "99 " + skill, detail).skill(skill, 99)));
			}
			else if (everyLevel || levelNow % 10 == 0)
			{
				String title = levelNow - levelBefore > 1 ? skill + " " + levelBefore + " to " + levelNow : skill + " " + levelNow;
				Entry level = new Entry(Entry.Kind.LEVEL, now, title, "Level up").skill(skill, levelNow);
				level.from = levelBefore;
				written.add(add(level));
			}
			int totalNow = totalLevel();
			int maxTotal = levels.size() * 99;
			if (totalNow >= maxTotal && totalBefore < maxTotal)
			{
				written.add(add(new Entry(Entry.Kind.TOTAL, now, "Total level " + number(totalNow), "The highest total there is")));
			}
			else if (totalNow / 100 > totalBefore / 100 && totalNow >= 500)
			{
				int milestone = totalNow / 100 * 100;
				written.add(add(new Entry(Entry.Kind.TOTAL, now, "Total level " + number(milestone), "Total level milestone")));
			}
		}

		for (long mark : SKILL_XP)
		{
			if (xpBefore < mark && xpNow >= mark)
			{
				String detail = mark == MAX_XP ? "The most experience a skill can hold" : "Experience milestone";
				written.add(add(new Entry(Entry.Kind.XP, now, (mark / 1_000_000) + "M " + skill, detail).skill(skill, levelNow)));
			}
		}
		long totalXpNow = totalXp();
		long totalXpBefore = totalXpNow - xpNow + xpBefore;
		long mark = totalXpMilestone(totalXpBefore, totalXpNow);
		if (mark > 0)
		{
			written.add(add(new Entry(Entry.Kind.XP, now, shortAmount(mark) + " total experience", "Experience milestone")));
		}
		return written;
	}

	/** The local player's combat level, read each tick; only round numbers and the maximum are written. */
	public Entry combat(int level, long now)
	{
		if (!isBegun() || level <= combat)
		{
			if (level > 0 && combat == 0)
			{
				combat = level;
			}
			return null;
		}
		int before = combat;
		combat = level;
		if (before == 0)
		{
			return null;
		}
		if (level >= 126)
		{
			return add(new Entry(Entry.Kind.COMBAT, now, "Combat level 126", "The highest combat level there is"));
		}
		if (level / 10 > before / 10 && level >= 50)
		{
			return add(new Entry(Entry.Kind.COMBAT, now, "Combat level " + (level / 10 * 10), "Combat milestone"));
		}
		return null;
	}

	/** The game announced a kill count. The year counts every kill; the annals keep the first and the round numbers. */
	public Entry killCount(String name, int count, long now, ZoneId zone)
	{
		if (!isBegun() || count <= 0)
		{
			return null;
		}
		Integer before = kc.put(name, count);
		int gained = before == null || count <= before || count - before > 500 ? 1 : count - before;
		if (before != null && count == before)
		{
			return null;
		}
		year(now, zone).kills.merge(name, gained, Integer::sum);
		if (count == 1)
		{
			return add(new Entry(Entry.Kind.BOSS, now, "First " + name, "Kill count 1").skill(null, 1));
		}
		for (int milestone : KC_MILESTONES)
		{
			if (count == milestone || (before != null && before < milestone && count > milestone))
			{
				return add(new Entry(Entry.Kind.BOSS, now, name + " " + number(milestone), "Kill count milestone").skill(null, milestone));
			}
		}
		return null;
	}

	/**
	 * A single drop worth telling of. The detail names where it came from; its value goes with it.
	 * A drop that also filled a collection log slot is one line, not two: the slot takes the drop's value.
	 */
	public Entry drop(String item, int quantity, int itemId, long value, String source, long now)
	{
		if (!isBegun())
		{
			return null;
		}
		Entry slot = recent(Entry.Kind.COLLECTION, item, now);
		if (slot != null)
		{
			slot.itemId = itemId;
			slot.value = value;
			slot.detail = source == null ? "New collection log slot" : "New log slot from " + source;
			return slot;
		}
		String title = quantity > 1 ? number(quantity) + " x " + item : item;
		return add(new Entry(Entry.Kind.DROP, now, title, source == null ? "Notable drop" : "From " + source).item(itemId, value));
	}

	/** An entry of a kind about an item written in the last moments, or null. */
	private Entry recent(Entry.Kind kind, String title, long now)
	{
		for (int i = entries.size() - 1; i >= 0; i--)
		{
			Entry e = entries.get(i);
			if (now - e.at > MERGE_MS)
			{
				return null;
			}
			if (e.getKind() == kind && e.getTitle().equalsIgnoreCase(title))
			{
				return e;
			}
		}
		return null;
	}

	/** Files an entry read from the chat box. Clues are all counted, but only the milestones are kept. */
	public Entry record(Entry entry, long now, ZoneId zone)
	{
		if (!isBegun() || entry == null)
		{
			return null;
		}
		if (entry.getKind() == Entry.Kind.COLLECTION)
		{
			Entry drop = recent(Entry.Kind.DROP, entry.getTitle(), now);
			if (drop != null)
			{
				drop.kind = Entry.Kind.COLLECTION;
				drop.detail = drop.detail.startsWith("From ") ? "New log slot from " + drop.detail.substring(5) : entry.detail;
				return drop;
			}
		}
		if (entry.getKind() == Entry.Kind.CLUE)
		{
			year(now, zone).clues++;
			if (!ChatParser.clueMilestone(entry.level))
			{
				return null;
			}
		}
		return add(entry);
	}

	/**
	 * Gives recent entries named after an item, such as a collection log slot, that item's
	 * picture once the loot it came from is seen.
	 */
	public void attachItem(String name, int itemId, long since)
	{
		for (int i = entries.size() - 1; i >= 0; i--)
		{
			Entry e = entries.get(i);
			if (e.at < since)
			{
				break;
			}
			if (e.itemId == 0 && e.getTitle().equalsIgnoreCase(name))
			{
				e.itemId = itemId;
			}
		}
	}

	/** Time logged in. Called every game tick with the time it stands for. */
	public void tick(long now, long ms, ZoneId zone)
	{
		if (!isBegun())
		{
			return;
		}
		Year year = year(now, zone);
		year.playedMs += ms;
		long day = Instant.ofEpochMilli(now).atZone(zone).toLocalDate().toEpochDay();
		if (year.days.isEmpty() || year.days.get(year.days.size() - 1) != day)
		{
			if (!year.days.contains(day))
			{
				year.days.add(day);
				Collections.sort(year.days);
			}
		}
	}

	/** The year a moment falls in, begun from the last readings if it is new. */
	Year year(long now, ZoneId zone)
	{
		int number = ZonedDateTime.ofInstant(Instant.ofEpochMilli(now), zone).getYear();
		Year last = years.isEmpty() ? null : years.get(years.size() - 1);
		if (last != null && last.year == number)
		{
			return last;
		}
		Year found = getYear(number);
		if (found != null)
		{
			return found;
		}
		Year year = new Year(number);
		year.startXp.putAll(xp);
		year.endXp.putAll(xp);
		year.startLevel.putAll(levels);
		year.endLevel.putAll(levels);
		years.add(year);
		years.sort((a, b) -> Integer.compare(a.year, b.year));
		return year;
	}

	int totalLevel()
	{
		int total = 0;
		for (int level : levels.values())
		{
			total += level;
		}
		return total;
	}

	long totalXp()
	{
		long total = 0;
		for (long x : xp.values())
		{
			total += x;
		}
		return total;
	}

	private Entry add(Entry entry)
	{
		entries.add(entry);
		if (entries.size() > MAX_ENTRIES)
		{
			compact();
		}
		return entry;
	}

	/** Drops the least telling entry, the oldest of them on a tie, until the annals fit. */
	private void compact()
	{
		while (entries.size() > MAX_ENTRIES)
		{
			int worst = -1;
			for (int i = 0; i < entries.size() - 1; i++)
			{
				Entry e = entries.get(i);
				if (e.getKind() == Entry.Kind.BEGIN)
				{
					continue;
				}
				if (worst < 0 || e.rank() < entries.get(worst).rank())
				{
					worst = i;
				}
			}
			if (worst < 0)
			{
				return;
			}
			entries.remove(worst);
		}
	}

	/** The total experience mark crossed between two readings, or 0. */
	static long totalXpMilestone(long before, long now)
	{
		long[] marks = {10_000_000L, 25_000_000L, 50_000_000L, 100_000_000L, 250_000_000L, 500_000_000L};
		long found = 0;
		for (long mark : marks)
		{
			if (before < mark && now >= mark)
			{
				found = mark;
			}
		}
		// Past half a billion, every further half billion.
		long step = 500_000_000L;
		if (now >= step * 2 && before / step < now / step)
		{
			found = now / step * step;
		}
		return found;
	}

	static String shortAmount(long n)
	{
		if (n >= 1_000_000_000L)
		{
			String text = String.format(Locale.ENGLISH, "%.1f", n / 1_000_000_000.0);
			return (text.endsWith(".0") ? text.substring(0, text.length() - 2) : text) + "B";
		}
		return n / 1_000_000 + "M";
	}

	static String number(long n)
	{
		return String.format(Locale.ENGLISH, "%,d", n);
	}
}

package com.codex.annals.core;

import java.util.ArrayList;
import java.util.List;

/** Where the account stood on the day the annals began: the prologue to everything written after. */
public class Baseline
{
	long at;
	int totalLevel;
	long totalXp;
	int combat;
	int questPoints;
	int questsDone;
	int questsTotal;
	List<String> maxed = new ArrayList<>();

	Baseline()
	{
	}

	public Baseline(long at, int totalLevel, long totalXp, int combat, int questPoints, int questsDone, int questsTotal, List<String> maxed)
	{
		this.at = at;
		this.totalLevel = totalLevel;
		this.totalXp = totalXp;
		this.combat = combat;
		this.questPoints = questPoints;
		this.questsDone = questsDone;
		this.questsTotal = questsTotal;
		this.maxed = new ArrayList<>(maxed);
	}

	public long getAt()
	{
		return at;
	}

	public int getTotalLevel()
	{
		return totalLevel;
	}

	public long getTotalXp()
	{
		return totalXp;
	}

	public int getCombat()
	{
		return combat;
	}

	public int getQuestPoints()
	{
		return questPoints;
	}

	public int getQuestsDone()
	{
		return questsDone;
	}

	public int getQuestsTotal()
	{
		return questsTotal;
	}

	public List<String> getMaxed()
	{
		return maxed == null ? new ArrayList<>() : maxed;
	}
}

package com.codex.annals.core;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reads the game's own messages for the things the annals keep. It takes the message with its
 * colour tags already removed and answers with what it found, or null.
 */
public final class ChatParser
{
	private static final Pattern KILL_COUNT = Pattern.compile(
		"^Your (?:completed |subdued )?(.+?) (?:kill |success |completion )?count is: ?([\\d,]+)\\b");
	private static final Pattern COLLECTION = Pattern.compile("^New item added to your collection log: (.+?)\\.?$");
	private static final Pattern QUEST = Pattern.compile("^Congratulations,? you've completed a quest: (.+?)\\.?$");
	private static final Pattern DIARY = Pattern.compile(
		"^Congratulations! You have completed all of the (\\w+) tasks in the (.+?) area\\b");
	private static final Pattern TASK = Pattern.compile(
		"^Congratulations, you've completed an? (\\w+) combat task: (.+?)(?: \\(\\d+ points?\\))?\\.?$");
	private static final Pattern CLUE = Pattern.compile("^You have completed ([\\d,]+) (\\w+) Treasure Trails?\\.?$");
	private static final String[] PET_LINES = {
		"You have a funny feeling like you're being followed",
		"You feel something weird sneaking into your backpack",
	};

	/** A kill count the game announced. */
	public static final class KillCount
	{
		private final String name;
		private final int count;

		KillCount(String name, int count)
		{
			this.name = name;
			this.count = count;
		}

		public String getName()
		{
			return name;
		}

		public int getCount()
		{
			return count;
		}
	}

	private ChatParser()
	{
	}

	public static KillCount killCount(String message)
	{
		Matcher m = KILL_COUNT.matcher(message);
		if (!m.find())
		{
			return null;
		}
		try
		{
			return new KillCount(m.group(1), Integer.parseInt(m.group(2).replace(",", "")));
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/**
	 * The entry the message tells of, or null.
	 *
	 * @param recentKill the boss whose kill count was just announced, to say where a pet came from
	 */
	public static Entry entry(String message, long now, String recentKill)
	{
		for (String line : PET_LINES)
		{
			if (message.startsWith(line))
			{
				return new Entry(Entry.Kind.PET, now, "A pet followed you home",
					recentKill == null ? "The rarest drop of all" : "While killing " + recentKill);
			}
		}
		Matcher m = COLLECTION.matcher(message);
		if (m.find())
		{
			return new Entry(Entry.Kind.COLLECTION, now, m.group(1), "New collection log slot");
		}
		m = QUEST.matcher(message);
		if (m.find())
		{
			return new Entry(Entry.Kind.QUEST, now, m.group(1), "Quest complete");
		}
		m = DIARY.matcher(message);
		if (m.find())
		{
			return new Entry(Entry.Kind.DIARY, now, m.group(2) + " " + m.group(1).toLowerCase() + " diary", "Achievement diary complete");
		}
		m = TASK.matcher(message);
		if (m.find())
		{
			return new Entry(Entry.Kind.TASK, now, m.group(2), capital(m.group(1)) + " combat task");
		}
		m = CLUE.matcher(message);
		if (m.find())
		{
			int count;
			try
			{
				count = Integer.parseInt(m.group(1).replace(",", ""));
			}
			catch (NumberFormatException e)
			{
				return null;
			}
			// Every clue is counted for the year, but only the first and the round numbers are written down.
			Entry clue = new Entry(Entry.Kind.CLUE, now, capital(m.group(2)) + " clue number " + m.group(1),
				count == 1 ? "Your first of this tier" : "Treasure Trails milestone");
			clue.level = count;
			return clue;
		}
		return null;
	}

	/** Whether a clue count is worth its own line: the first, then 10, 25, 50, 100 and every hundred after. */
	public static boolean clueMilestone(int count)
	{
		return count == 1 || count == 10 || count == 25 || count == 50 || (count >= 100 && count % 100 == 0);
	}

	static String capital(String word)
	{
		return word.isEmpty() ? word : Character.toUpperCase(word.charAt(0)) + word.substring(1).toLowerCase();
	}
}

package com.codex.annals.core;

/** One line in the annals: a level, a quest, a pet, a first kill, a drop worth telling of. */
public class Entry
{
	/** What kind of entry it is; the weight is how much it matters when only a few fit. */
	public enum Kind
	{
		PET(100, Chapter.LOOT),
		MAX(95, Chapter.SKILLS),
		COLLECTION(76, Chapter.LOOT),
		DROP(72, Chapter.LOOT),
		TOTAL(70, Chapter.SKILLS),
		DIARY(64, Chapter.FEATS),
		QUEST(60, Chapter.FEATS),
		BOSS(58, Chapter.BOSSES),
		XP(52, Chapter.SKILLS),
		COMBAT(46, Chapter.SKILLS),
		TASK(40, Chapter.FEATS),
		CLUE(28, Chapter.LOOT),
		LEVEL(20, Chapter.SKILLS),
		BEGIN(10, Chapter.ALL);

		private final int weight;
		private final Chapter chapter;

		Kind(int weight, Chapter chapter)
		{
			this.weight = weight;
			this.chapter = chapter;
		}

		public int getWeight()
		{
			return weight;
		}

		public Chapter getChapter()
		{
			return chapter;
		}
	}

	/** The timeline's filters. */
	public enum Chapter
	{
		ALL,
		SKILLS,
		FEATS,
		LOOT,
		BOSSES
	}

	Kind kind;
	long at;
	String title;
	String detail;
	String skill;
	int itemId;
	long value;
	int level;
	/** The level a level entry rose from. */
	int from;

	Entry()
	{
	}

	public Entry(Kind kind, long at, String title, String detail)
	{
		this.kind = kind;
		this.at = at;
		this.title = title;
		this.detail = detail;
	}

	Entry skill(String skill, int level)
	{
		this.skill = skill;
		this.level = level;
		return this;
	}

	Entry item(int itemId, long value)
	{
		this.itemId = itemId;
		this.value = value;
		return this;
	}

	public Kind getKind()
	{
		return kind == null ? Kind.LEVEL : kind;
	}

	public long getAt()
	{
		return at;
	}

	public String getTitle()
	{
		return title == null ? "" : title;
	}

	public String getDetail()
	{
		return detail;
	}

	/** The skill a level, 99 or experience entry belongs to, or null. */
	public String getSkill()
	{
		return skill;
	}

	/** The level reached, for a level or 99 entry. */
	public int getLevel()
	{
		return level;
	}

	public int getItemId()
	{
		return itemId;
	}

	public long getValue()
	{
		return value;
	}

	/** How much the entry matters when only a few fit: its kind, then a drop's size. */
	public double rank()
	{
		double bonus = value > 0 ? Math.min(25, Math.log10(Math.max(1, value)) * 2.5) : 0;
		if (getKind() == Kind.LEVEL)
		{
			bonus = level / 10.0;
		}
		return getKind().getWeight() + bonus;
	}

	public boolean in(Chapter chapter)
	{
		return chapter == Chapter.ALL || getKind().getChapter() == chapter;
	}
}

package com.codex.annals.core;

import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Map;

/**
 * A year told as one story, ready for the Year tab and the Year in Gielinor card: the totals,
 * the skills and bosses it was spent on, how the days fell across the months and the entries
 * that mattered most.
 */
public final class Recap
{
	/** One skill's year. */
	public static final class SkillYear
	{
		private final String skill;
		private final long gained;
		private final int startLevel;
		private final int endLevel;

		SkillYear(String skill, long gained, int startLevel, int endLevel)
		{
			this.skill = skill;
			this.gained = gained;
			this.startLevel = startLevel;
			this.endLevel = endLevel;
		}

		public String getSkill()
		{
			return skill;
		}

		public long getGained()
		{
			return gained;
		}

		public int getStartLevel()
		{
			return startLevel;
		}

		public int getEndLevel()
		{
			return endLevel;
		}
	}

	/** One boss or activity's year. */
	public static final class KillYear
	{
		private final String name;
		private final int kills;
		private final int killCount;

		KillYear(String name, int kills, int killCount)
		{
			this.name = name;
			this.kills = kills;
			this.killCount = killCount;
		}

		public String getName()
		{
			return name;
		}

		public int getKills()
		{
			return kills;
		}

		/** The game's own count after the year, or 0. */
		public int getKillCount()
		{
			return killCount;
		}
	}

	private final int year;
	private final String player;
	private final long playedMs;
	private final int daysPlayed;
	private final int longestStreak;
	private final long xpGained;
	private final int levelsGained;
	private final int kills;
	private final int[] monthDays = new int[12];
	private final int[] monthEntries = new int[12];
	private final List<SkillYear> skills = new ArrayList<>();
	private final List<KillYear> bosses = new ArrayList<>();
	private final List<Entry> highlights = new ArrayList<>();
	private final Entry biggestDrop;
	private int quests;
	private int diaries;
	private int tasks;
	private int collection;
	private int pets;
	private int maxes;
	private final int clues;
	private final String headline;
	private final long begunAt;

	private Recap(Annals annals, Year y, ZoneId zone, int highlightCount)
	{
		year = y.year;
		player = annals.getPlayer();
		begunAt = annals.getBegunAt();
		playedMs = y.playedMs;
		daysPlayed = y.days.size();
		longestStreak = streak(y.days);
		xpGained = y.totalGained();
		levelsGained = y.levelsGained();
		kills = y.totalKills();
		clues = y.clues;
		for (long day : y.days)
		{
			monthDays[LocalDate.ofEpochDay(day).getMonthValue() - 1]++;
		}

		for (String skill : y.endXp.keySet())
		{
			long gained = y.gained(skill);
			if (gained > 0)
			{
				skills.add(new SkillYear(skill, gained, y.startLevel(skill), y.endLevel(skill)));
			}
		}
		skills.sort(Comparator.comparingLong(SkillYear::getGained).reversed());
		for (Map.Entry<String, Integer> e : y.kills.entrySet())
		{
			Integer kc = annals.kc.get(e.getKey());
			bosses.add(new KillYear(e.getKey(), e.getValue(), kc == null ? 0 : kc));
		}
		bosses.sort(Comparator.comparingInt(KillYear::getKills).reversed());

		List<Entry> inYear = new ArrayList<>();
		Entry drop = null;
		for (Entry e : annals.entries)
		{
			LocalDate date = Instant.ofEpochMilli(e.at).atZone(zone).toLocalDate();
			if (date.getYear() != year)
			{
				continue;
			}
			monthEntries[date.getMonthValue() - 1]++;
			switch (e.getKind())
			{
				case QUEST:
					quests++;
					break;
				case DIARY:
					diaries++;
					break;
				case TASK:
					tasks++;
					break;
				case COLLECTION:
					collection++;
					if (e.value > 0 && (drop == null || e.value > drop.value))
					{
						drop = e;
					}
					break;
				case PET:
					pets++;
					break;
				case MAX:
					maxes++;
					break;
				case DROP:
					if (drop == null || e.value > drop.value)
					{
						drop = e;
					}
					break;
				default:
					break;
			}
			if (e.getKind() != Entry.Kind.BEGIN)
			{
				inYear.add(e);
			}
		}
		biggestDrop = drop;
		inYear.sort(Comparator.comparingDouble(Entry::rank).reversed().thenComparingLong(Entry::getAt));
		for (int i = 0; i < inYear.size() && highlights.size() < highlightCount; i++)
		{
			highlights.add(inYear.get(i));
		}
		headline = headline(inYear);
	}

	/** The recap of one year, or null if the annals have nothing for it. */
	public static Recap of(Annals annals, int year, ZoneId zone)
	{
		Year y = annals.getYear(year);
		return y == null ? null : new Recap(annals, y, zone, 6);
	}

	/** The years the annals hold, newest first. */
	public static List<Integer> years(Annals annals)
	{
		List<Integer> list = new ArrayList<>();
		for (Year y : annals.getYears())
		{
			list.add(y.year);
		}
		Collections.reverse(list);
		return list;
	}

	private String headline(List<Entry> ranked)
	{
		if (maxes > 1)
		{
			return "The year of " + count(maxes) + " 99s";
		}
		if (maxes == 1)
		{
			for (Entry e : ranked)
			{
				if (e.getKind() == Entry.Kind.MAX)
				{
					return "The year of " + e.getTitle();
				}
			}
		}
		if (pets > 0)
		{
			return pets == 1 ? "The year a pet came home" : "The year of " + count(pets) + " pets";
		}
		if (!bosses.isEmpty() && bosses.get(0).kills >= 100)
		{
			return "The year of " + bosses.get(0).name;
		}
		if (!skills.isEmpty())
		{
			return "A year of " + skills.get(0).skill;
		}
		return "A quiet year";
	}

	private static String count(int n)
	{
		String[] words = {"zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve"};
		return n < words.length ? words[n] : String.valueOf(n);
	}

	/** The longest run of days played back to back. */
	static int streak(List<Long> days)
	{
		int best = 0;
		int run = 0;
		long last = Long.MIN_VALUE;
		for (long day : days)
		{
			run = day == last + 1 ? run + 1 : 1;
			best = Math.max(best, run);
			last = day;
		}
		return best;
	}

	public int getYear()
	{
		return year;
	}

	public String getPlayer()
	{
		return player;
	}

	public long getBegunAt()
	{
		return begunAt;
	}

	public long getPlayedMs()
	{
		return playedMs;
	}

	public int getDaysPlayed()
	{
		return daysPlayed;
	}

	public int getLongestStreak()
	{
		return longestStreak;
	}

	public long getXpGained()
	{
		return xpGained;
	}

	public int getLevelsGained()
	{
		return levelsGained;
	}

	public int getKills()
	{
		return kills;
	}

	/** Days played in each month, January first. */
	public int[] getMonthDays()
	{
		return monthDays.clone();
	}

	/** Entries written in each month, January first. */
	public int[] getMonthEntries()
	{
		return monthEntries.clone();
	}

	/** The busiest month by days played, 0 for January, or -1 if no day was played. */
	public int busiestMonth()
	{
		int best = -1;
		for (int m = 0; m < 12; m++)
		{
			if (monthDays[m] > 0 && (best < 0 || monthDays[m] > monthDays[best]))
			{
				best = m;
			}
		}
		return best;
	}

	public List<SkillYear> getSkills()
	{
		return Collections.unmodifiableList(skills);
	}

	public List<KillYear> getBosses()
	{
		return Collections.unmodifiableList(bosses);
	}

	public List<Entry> getHighlights()
	{
		return Collections.unmodifiableList(highlights);
	}

	public Entry getBiggestDrop()
	{
		return biggestDrop;
	}

	public int getQuests()
	{
		return quests;
	}

	public int getDiaries()
	{
		return diaries;
	}

	public int getTasks()
	{
		return tasks;
	}

	public int getCollection()
	{
		return collection;
	}

	public int getPets()
	{
		return pets;
	}

	public int getMaxes()
	{
		return maxes;
	}

	public int getClues()
	{
		return clues;
	}

	public String getHeadline()
	{
		return headline;
	}
}

package com.codex.annals.core;

import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * The annals as the timeline shows them: newest first, in one chapter, with a day's ordinary
 * levels folded into a single line so a long grind does not bury the rest.
 */
public final class Timeline
{
	/** One line on the timeline: an entry, or a day's levels folded together. */
	public static final class Row
	{
		private final Entry entry;
		private final LocalDate date;
		private final int folded;

		Row(Entry entry, LocalDate date, int folded)
		{
			this.entry = entry;
			this.date = date;
			this.folded = folded;
		}

		public Entry getEntry()
		{
			return entry;
		}

		public LocalDate getDate()
		{
			return date;
		}

		/** How many level entries this row stands for, or 0 for a single entry. */
		public int getFolded()
		{
			return folded;
		}
	}

	private Timeline()
	{
	}

	public static List<Row> rows(List<Entry> entries, Entry.Chapter chapter, ZoneId zone)
	{
		List<Row> rows = new ArrayList<>();
		int i = entries.size() - 1;
		while (i >= 0)
		{
			Entry e = entries.get(i);
			if (!e.in(chapter))
			{
				i--;
				continue;
			}
			LocalDate date = Instant.ofEpochMilli(e.at).atZone(zone).toLocalDate();
			if (e.getKind() != Entry.Kind.LEVEL)
			{
				rows.add(new Row(e, date, 0));
				i--;
				continue;
			}
			// Gather every level of the day that sits next to this one, skipping nothing else.
			List<Entry> day = new ArrayList<>();
			int j = i;
			while (j >= 0 && entries.get(j).getKind() == Entry.Kind.LEVEL
				&& Instant.ofEpochMilli(entries.get(j).at).atZone(zone).toLocalDate().equals(date))
			{
				day.add(entries.get(j));
				j--;
			}
			i = j;
			if (day.size() == 1)
			{
				rows.add(new Row(e, date, 0));
				continue;
			}
			rows.add(new Row(fold(day), date, day.size()));
		}
		return rows;
	}

	/** One line for a day of levels: "Mining 61 to 64", or "6 levels" naming where each skill ended. */
	static Entry fold(List<Entry> newestFirst)
	{
		Map<String, int[]> bySkill = new LinkedHashMap<>();
		for (Entry e : newestFirst)
		{
			String skill = e.getSkill() == null ? e.getTitle() : e.getSkill();
			int[] range = bySkill.get(skill);
			int from = fromLevel(e);
			if (range == null)
			{
				bySkill.put(skill, new int[]{from, e.level});
			}
			else
			{
				range[0] = Math.min(range[0], from);
				range[1] = Math.max(range[1], e.level);
			}
		}
		Entry newest = newestFirst.get(0);
		Entry folded = new Entry(Entry.Kind.LEVEL, newest.at, null, null);
		int levels = 0;
		for (int[] range : bySkill.values())
		{
			levels += range[1] - range[0];
		}
		if (bySkill.size() == 1)
		{
			Map.Entry<String, int[]> only = bySkill.entrySet().iterator().next();
			folded.title = only.getKey() + " " + only.getValue()[0] + " to " + only.getValue()[1];
			folded.detail = levels + " levels in a day";
			folded.skill = only.getKey();
			folded.level = only.getValue()[1];
			return folded;
		}
		folded.title = levels + " levels";
		StringBuilder detail = new StringBuilder();
		for (Map.Entry<String, int[]> s : bySkill.entrySet())
		{
			if (detail.length() > 0)
			{
				detail.append(", ");
			}
			detail.append(s.getKey()).append(' ').append(s.getValue()[1]);
		}
		folded.detail = detail.toString();
		folded.skill = bySkill.keySet().iterator().next();
		folded.level = bySkill.values().iterator().next()[1];
		return folded;
	}

	/** The level an entry rose from; older saves without it rose by one. */
	private static int fromLevel(Entry e)
	{
		return e.from > 0 ? e.from : e.level - 1;
	}
}

package com.codex.annals.core;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** One calendar year of play: where every skill stood when it began and now, the days played and the kills. */
public class Year
{
	int year;
	Map<String, Long> startXp = new LinkedHashMap<>();
	Map<String, Long> endXp = new LinkedHashMap<>();
	Map<String, Integer> startLevel = new LinkedHashMap<>();
	Map<String, Integer> endLevel = new LinkedHashMap<>();
	/** Days played, as epoch days in the player's own time, oldest first. */
	List<Long> days = new ArrayList<>();
	long playedMs;
	Map<String, Integer> kills = new LinkedHashMap<>();
	int clues;

	Year()
	{
	}

	Year(int year)
	{
		this.year = year;
	}

	public int getYear()
	{
		return year;
	}

	public long getPlayedMs()
	{
		return playedMs;
	}

	public List<Long> getDays()
	{
		return days;
	}

	public Map<String, Integer> getKills()
	{
		return kills;
	}

	public int getClues()
	{
		return clues;
	}

	/** Makes sure every map exists after Gson has read an older save. */
	void repair()
	{
		if (startXp == null)
		{
			startXp = new LinkedHashMap<>();
		}
		if (endXp == null)
		{
			endXp = new LinkedHashMap<>();
		}
		if (startLevel == null)
		{
			startLevel = new LinkedHashMap<>();
		}
		if (endLevel == null)
		{
			endLevel = new LinkedHashMap<>();
		}
		if (days == null)
		{
			days = new ArrayList<>();
		}
		if (kills == null)
		{
			kills = new LinkedHashMap<>();
		}
	}

	/** Experience a skill gained this year. */
	public long gained(String skill)
	{
		Long start = startXp.get(skill);
		Long end = endXp.get(skill);
		return start == null || end == null ? 0 : Math.max(0, end - start);
	}

	public int startLevel(String skill)
	{
		Integer level = startLevel.get(skill);
		return level == null ? 0 : level;
	}

	public int endLevel(String skill)
	{
		Integer level = endLevel.get(skill);
		return level == null ? startLevel(skill) : level;
	}

	public long totalGained()
	{
		long total = 0;
		for (String skill : endXp.keySet())
		{
			total += gained(skill);
		}
		return total;
	}

	public int levelsGained()
	{
		int total = 0;
		for (String skill : endLevel.keySet())
		{
			total += Math.max(0, endLevel(skill) - startLevel(skill));
		}
		return total;
	}

	public int totalKills()
	{
		int total = 0;
		for (int k : kills.values())
		{
			total += k;
		}
		return total;
	}
}

package com.codex.annals.ui;

import java.awt.Component;
import javax.swing.Timer;

/** Eases a value toward its target on the Swing thread so rings and bars fill instead of jumping. */
final class Animator
{
	private static final int FRAME_MS = 16;
	private static final double EASE = 0.18;

	private final Component owner;
	private final Timer timer;
	private double value;
	private double target;

	Animator(Component owner)
	{
		this.owner = owner;
		this.timer = new Timer(FRAME_MS, e -> step());
	}

	double get()
	{
		return value;
	}

	void set(double newTarget, boolean animate)
	{
		target = newTarget;
		if (!animate || !owner.isShowing())
		{
			value = newTarget;
			timer.stop();
			owner.repaint();
			return;
		}
		if (!timer.isRunning())
		{
			timer.start();
		}
	}

	private void step()
	{
		value += (target - value) * EASE;
		if (Math.abs(target - value) < 0.002 || !owner.isShowing())
		{
			value = target;
			timer.stop();
		}
		owner.repaint();
	}
}

package com.codex.annals.ui;

import com.codex.annals.core.Annals;
import com.codex.annals.core.Recap;
import com.codex.annals.core.Year;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Graphics;
import java.awt.image.BufferedImage;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.PluginPanel;

/**
 * The Codex Annals side panel: the crest, then three pages. Timeline is the account's whole
 * history, Year is one year told in full, and Card is that year as a picture to save or copy.
 */
public class AnnalsPanel extends PluginPanel
{
	private static final String[] TABS = {"timeline", "year", "card"};
	private static final int PAGE = 120;
	/** The most years the chooser offers at once; the newest are kept. */
	private static final int YEARS_SHOWN = 4;

	private final ItemIcons items;
	private final Icons icons;
	private final CardActions actions;
	private final Crest crest = new Crest();
	private final Segmented tabs = new Segmented(true, "Timeline", "Year", "Card");
	private final Segmented chapters = new Segmented(false, TimelineView.CHAPTERS);
	private final CardLayout cards = new CardLayout();
	private final JPanel content = new JPanel(cards);
	private final JScrollPane timeline = scroller();
	private final JScrollPane year = scroller();
	private final JScrollPane card = scroller();

	private Annals annals;
	private ZoneId zone = ZoneId.systemDefault();
	private String playerName;
	private List<Integer> years = Collections.emptyList();
	private Segmented yearChooser;
	private int yearIndex;
	private int limit = PAGE;
	private boolean showName = true;
	private int tab;
	private String cardNote;
	private BufferedImage cardImage;
	private boolean refreshPending;

	public AnnalsPanel(ItemIcons items, Icons icons, CardActions actions)
	{
		super(false);
		this.items = items;
		this.icons = icons;
		this.actions = actions;
		setLayout(new BorderLayout());
		setBackground(Theme.INK);

		JPanel north = new JPanel(new BorderLayout());
		north.setOpaque(false);
		north.add(crest, BorderLayout.NORTH);
		JPanel tabHolder = new JPanel(new BorderLayout());
		tabHolder.setOpaque(false);
		tabHolder.setBorder(new EmptyBorder(8, 8, 2, 8));
		tabHolder.add(tabs, BorderLayout.CENTER);
		north.add(tabHolder, BorderLayout.SOUTH);
		add(north, BorderLayout.NORTH);

		content.setOpaque(false);
		content.add(timeline, TABS[0]);
		content.add(year, TABS[1]);
		content.add(card, TABS[2]);
		add(content, BorderLayout.CENTER);

		tabs.onChange(this::showTab);
		chapters.onChange(i ->
		{
			limit = PAGE;
			rebuildTimeline();
			SwingUtilities.invokeLater(() -> timeline.getVerticalScrollBar().setValue(0));
		});
		rebuildAll();
	}

	private static JScrollPane scroller()
	{
		JScrollPane scroll = new JScrollPane();
		scroll.setBorder(null);
		scroll.setOpaque(false);
		scroll.getViewport().setOpaque(false);
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.getVerticalScrollBar().setPreferredSize(new Dimension(8, 0));
		return scroll;
	}

	/**
	 * Called on the Swing thread whenever the annals change.
	 *
	 * @param annals a copy the panel may keep, or null when no account is loaded
	 */
	public void update(Annals annals, ZoneId zone, String playerName)
	{
		this.annals = annals;
		this.zone = zone;
		this.playerName = playerName;
		List<Integer> latest = annals == null ? Collections.emptyList() : Recap.years(annals);
		if (latest.size() > YEARS_SHOWN)
		{
			latest = new ArrayList<>(latest.subList(0, YEARS_SHOWN));
		}
		if (!latest.equals(years))
		{
			Integer chosen = yearIndex < years.size() ? years.get(yearIndex) : null;
			years = latest;
			yearIndex = Math.max(0, chosen == null ? 0 : years.indexOf(chosen));
			yearChooser = null;
			if (years.size() > 1)
			{
				String[] labels = new String[years.size()];
				for (int i = 0; i < labels.length; i++)
				{
					labels[i] = String.valueOf(years.get(i));
				}
				yearChooser = new Segmented(false, labels);
				yearChooser.setSelected(yearIndex, false);
				yearChooser.onChange(i ->
				{
					yearIndex = i;
					rebuildYear();
					if (tab == 2)
					{
						rebuildCard();
					}
				});
			}
		}
		rebuildAll();
	}

	public void setShowName(boolean showName)
	{
		this.showName = showName;
		if (tab == 2)
		{
			rebuildCard();
		}
	}

	/** A line under the card's buttons, such as where it was saved. */
	public void cardNote(String note)
	{
		cardNote = note;
		rebuildCard();
	}

	/** Opens one tab, for previews and tests. */
	public void showTab(int index)
	{
		tab = index;
		tabs.setSelected(index, false);
		cards.show(content, TABS[index]);
		if (index == 2)
		{
			cardNote = null;
			rebuildCard();
		}
	}

	/** Picks a chapter of the timeline, for previews and tests. */
	public void showChapter(int index)
	{
		chapters.setSelected(index, true);
	}

	private void rebuildAll()
	{
		Year thisYear = annals == null ? null : annals.getYear(LocalDate.now(zone).getYear());
		crest.update(playerName != null ? playerName : annals == null ? null : annals.getPlayer(),
			annals == null ? 0 : annals.getBegunAt(),
			annals == null ? 0 : annals.getEntries().size(),
			thisYear == null ? 0 : thisYear.getDays().size(),
			thisYear == null ? 0 : thisYear.getPlayedMs());
		rebuildTimeline();
		rebuildYear();
		if (tab == 2)
		{
			rebuildCard();
		}
	}

	private void rebuildTimeline()
	{
		replace(timeline, TimelineView.build(annals, zone, chapters, limit, () ->
		{
			limit += PAGE;
			rebuildTimeline();
		}, items, icons, this::refreshLater));
	}

	private Recap recap()
	{
		if (annals == null || years.isEmpty())
		{
			return null;
		}
		return Recap.of(annals, years.get(Math.min(yearIndex, years.size() - 1)), zone);
	}

	private void rebuildYear()
	{
		Recap r = recap();
		LocalDate today = LocalDate.now(zone);
		int current = r != null && r.getYear() == today.getYear() ? today.getMonthValue() - 1 : -1;
		replace(year, YearView.build(r, yearChooser, current, zone, items, icons, this::refreshLater));
	}

	private void rebuildCard()
	{
		StackPanel stack = new StackPanel(8, 8);
		if (yearChooser != null)
		{
			stack.add(yearChooser);
		}
		Recap r = recap();
		if (r == null)
		{
			stack.add(Views.note("Nothing to share yet", "Once the annals have begun, your Year in Gielinor card appears here, ready to save or copy. It grows all year."));
			replace(card, stack);
			return;
		}
		int shownYear = r.getYear();
		cardImage = YearCard.render(r, showName, items, icons, this::refreshLater);
		JPanel buttons = new JPanel(new FlowLayout(FlowLayout.CENTER, 6, 0));
		buttons.setOpaque(false);
		buttons.add(new CodexButton("Save card", true, () -> actions.save(cardImage, shownYear)));
		buttons.add(new CodexButton("Copy to clipboard", false, () -> actions.copy(cardImage)));
		boolean thisYear = shownYear == LocalDate.now(zone).getYear();
		stack.add(new SectionHeader("Year in Gielinor", thisYear ? "so far" : String.valueOf(shownYear)));
		stack.add(new CardPreview(cardImage));
		stack.add(buttons);
		String note = cardNote != null ? cardNote : "Save card asks where to put the picture. Copy puts it on the clipboard, ready to paste.";
		stack.add(Ui.wrapped(note, Theme.small(), cardNote != null ? Theme.TEAL : Theme.TEXT_FAINT, Views.WIDTH - 10));
		replace(card, stack);
	}

	/** Item pictures arrive after the first drawing; redraw once they are in. */
	private void refreshLater()
	{
		if (refreshPending)
		{
			return;
		}
		refreshPending = true;
		SwingUtilities.invokeLater(() ->
		{
			refreshPending = false;
			if (tab == 2)
			{
				rebuildCard();
			}
			else
			{
				timeline.repaint();
				year.repaint();
			}
		});
	}

	private static void replace(JScrollPane scroll, JComponent view)
	{
		int position = scroll.getVerticalScrollBar().getValue();
		scroll.setViewportView(view);
		scroll.revalidate();
		SwingUtilities.invokeLater(() -> scroll.getVerticalScrollBar().setValue(position));
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		g.setColor(Theme.INK);
		g.fillRect(0, 0, getWidth(), getHeight());
	}
}

package com.codex.annals.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import java.util.List;
import java.util.function.IntConsumer;
import javax.swing.JComponent;

/**
 * Recent sessions as a row of bars, oldest on the left. The tallest is gilded, hovering names
 * a bar and clicking opens that session.
 */
class BarChart extends JComponent
{
	private static final int LABEL_H = 14;

	/** One bar. */
	static final class Bar
	{
		final String label;
		final String tip;
		final long value;

		Bar(String label, String tip, long value)
		{
			this.label = label;
			this.tip = tip;
			this.value = value;
		}
	}

	private final List<Bar> bars;
	private final Color color;
	private int hover = -1;

	BarChart(List<Bar> bars, Color color, IntConsumer onClick)
	{
		this.bars = bars;
		this.color = color;
		setOpaque(false);
		setPreferredSize(new Dimension(10, 92));
		setToolTipText("");
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				int index = indexAt(e.getX());
				if (index != hover)
				{
					hover = index;
					repaint();
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = -1;
				repaint();
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				int index = indexAt(e.getX());
				if (index >= 0 && onClick != null)
				{
					onClick.accept(index);
				}
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	private int indexAt(int x)
	{
		if (bars.isEmpty())
		{
			return -1;
		}
		int index = x * bars.size() / Math.max(1, getWidth());
		return index >= 0 && index < bars.size() ? index : -1;
	}

	@Override
	public String getToolTipText(MouseEvent e)
	{
		int index = indexAt(e.getX());
		return index < 0 ? null : bars.get(index).tip;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight() - LABEL_H;
		long max = 1;
		int best = -1;
		for (int i = 0; i < bars.size(); i++)
		{
			if (bars.get(i).value > max)
			{
				max = bars.get(i).value;
				best = i;
			}
		}

		// Faint guide lines at the half and the top.
		g.setColor(Theme.alpha(Theme.STROKE_SOFT, 160));
		g.drawLine(0, 4, w, 4);
		g.drawLine(0, 4 + (h - 4) / 2, w, 4 + (h - 4) / 2);
		g.setColor(Theme.STROKE);
		g.drawLine(0, h, w, h);

		float slot = w / (float) Math.max(1, bars.size());
		float bw = Math.max(3, Math.min(16, slot - 4));
		g.setFont(Theme.small());
		FontMetrics fm = g.getFontMetrics();
		for (int i = 0; i < bars.size(); i++)
		{
			Bar bar = bars.get(i);
			float x = i * slot + (slot - bw) / 2;
			float bh = bar.value <= 0 ? 0 : Math.max(3, (h - 6) * bar.value / (float) max);
			Color c = i == best ? Theme.GOLD_BRIGHT : color;
			if (i == hover)
			{
				g.setColor(Theme.alpha(Theme.GOLD, 26));
				g.fillRect(Math.round(i * slot), 0, Math.round(slot), h);
			}
			if (bh > 0)
			{
				RoundRectangle2D shape = new RoundRectangle2D.Float(x, h - bh, bw, bh + 3, 4, 4);
				g.setClip(0, 0, w, h);
				g.setPaint(new GradientPaint(0, h - bh, c, 0, h, Theme.mix(c, Theme.INK, 0.55)));
				g.fill(shape);
				g.setColor(Theme.alpha(java.awt.Color.WHITE, 50));
				g.drawLine(Math.round(x + 1), Math.round(h - bh + 1), Math.round(x + bw - 2), Math.round(h - bh + 1));
				g.setClip(null);
			}
			if (bars.size() <= 14 || i % 2 == bars.size() % 2)
			{
				String label = bar.label;
				g.setColor(i == hover ? Theme.TEXT : Theme.TEXT_FAINT);
				g.drawString(label, Math.round(i * slot + (slot - fm.stringWidth(label)) / 2), getHeight() - 2);
			}
		}
		g.dispose();
	}
}

package com.codex.annals.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.LayoutManager;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;

/**
 * A rounded, softly lit surface. Optionally clickable, with a hover lift and an
 * accent stripe down the left edge.
 */
public class Card extends JPanel
{
	private Color accent;
	private boolean hover;
	private boolean highlighted;
	private Runnable onClick;

	public Card(LayoutManager layout)
	{
		super(layout);
		setOpaque(false);
		setBorder(new EmptyBorder(8, 10, 8, 10));
	}

	public Card accent(Color color)
	{
		accent = color;
		repaint();
		return this;
	}

	/** A brighter rim for the card that matters most on screen. */
	public Card highlighted(boolean value)
	{
		highlighted = value;
		repaint();
		return this;
	}

	public Card onClick(Runnable action)
	{
		onClick = action;
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter adapter = new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				// Children forward their events here, so only clear hover when the pointer has really left.
				if (!contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					hover = false;
					repaint();
				}
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && onClick != null
					&& contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					onClick.run();
				}
			}
		};
		addMouseListener(adapter);
		Ui.forwardMouse(this, adapter);
		return this;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);

		Color top = hover ? Theme.CARD_HOVER : Theme.CARD_TOP;
		Color bottom = hover ? Theme.mix(Theme.CARD_HOVER, Theme.CARD, 0.5) : Theme.CARD;
		g.setPaint(new GradientPaint(0, 0, top, 0, h, bottom));
		g.fill(shape);

		if (accent != null)
		{
			g.setClip(shape);
			g.setPaint(new GradientPaint(0, 0, accent, 0, h, Theme.alpha(accent, 90)));
			g.fillRect(0, 0, 3, h);
			g.setClip(null);
		}

		Color rim = highlighted ? Theme.alpha(Theme.GOLD, 150) : hover ? Theme.alpha(Theme.GOLD, 90) : Theme.STROKE_SOFT;
		g.setColor(rim);
		g.draw(shape);

		// A one pixel sheen along the top edge, like light on vellum.
		g.setColor(Theme.alpha(Color.WHITE, hover ? 22 : 12));
		g.drawLine(Theme.RADIUS / 2, 1, w - Theme.RADIUS / 2, 1);
		g.dispose();
		super.paintComponent(graphics);
	}
}

