package com.codex.annals.ui;

import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;

/** The card shrunk to the panel's width, smoothly, with a soft shadow under it. */
class CardPreview extends JComponent
{
	private final BufferedImage card;
	private Image scaled;
	private int scaledWidth;

	CardPreview(BufferedImage card)
	{
		this.card = card;
		setOpaque(false);
		setPreferredSize(new Dimension(Views.WIDTH, Views.WIDTH * card.getHeight() / card.getWidth() + 4));
		setToolTipText("Your year card, as it will be saved");
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		// Fit the card inside the box, whichever of width or height runs out first.
		int w = Math.min(getWidth() - 2, (getHeight() - 4) * card.getWidth() / card.getHeight());
		if (w <= 0)
		{
			g.dispose();
			return;
		}
		int left = (getWidth() - w) / 2;
		if (scaled == null || scaledWidth != w)
		{
			scaled = shrink(card, w);
			scaledWidth = w;
		}
		g.setColor(Theme.alpha(java.awt.Color.BLACK, 90));
		g.fillRoundRect(left + 2, 4, w - 2, scaled.getHeight(null) - 2, 10, 10);
		g.drawImage(scaled, left, 0, null);
		g.dispose();
	}

	/** Halves the image step by step so the shrunk card keeps its detail. */
	private static Image shrink(BufferedImage image, int width)
	{
		BufferedImage current = image;
		while (current.getWidth() / 2 >= width)
		{
			current = resize(current, current.getWidth() / 2);
		}
		return current.getWidth() == width ? current : resize(current, width);
	}

	private static BufferedImage resize(BufferedImage image, int width)
	{
		int height = Math.max(1, image.getHeight() * width / image.getWidth());
		BufferedImage out = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = out.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
		g.drawImage(image, 0, 0, width, height, null);
		g.dispose();
		return out;
	}
}

package com.codex.annals.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A gilt-edged button; the primary style is filled, the quiet style is just an outline. */
public class CodexButton extends JComponent
{
	private final String text;
	private final boolean primary;
	private boolean hover;
	private boolean pressed;

	public CodexButton(String text, boolean primary, Runnable action)
	{
		this.text = text;
		this.primary = primary;
		setFont(Theme.small());
		setOpaque(false);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		FontMetrics fm = getFontMetrics(getFont());
		Dimension d = new Dimension(fm.stringWidth(text) + 20, 22);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = false;
				pressed = false;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				pressed = true;
				repaint();
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				boolean fire = pressed && contains(e.getPoint());
				pressed = false;
				repaint();
				if (fire)
				{
					action.run();
				}
			}
		});
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		int dy = pressed ? 1 : 0;
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f + dy, w - 1, h - 2, 8, 8);
		Color text;
		if (primary)
		{
			Color top = hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
			g.setPaint(new GradientPaint(0, 0, top, 0, h, Theme.GOLD_DIM));
			g.fill(shape);
			text = Theme.INK_DEEP;
		}
		else
		{
			g.setColor(hover ? Theme.alpha(Theme.GOLD, 40) : Theme.alpha(Theme.GOLD, 14));
			g.fill(shape);
			text = hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
		}
		g.setColor(Theme.alpha(Theme.GOLD, primary ? 220 : 140));
		g.draw(shape);
		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		g.setColor(text);
		g.drawString(this.text, (w - fm.stringWidth(this.text)) / 2, (h + fm.getAscent()) / 2 - 2 + dy);
		g.dispose();
	}
}

package com.codex.annals.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.RadialGradientPaint;
import java.awt.geom.Path2D;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/** The crest at the top of the panel: the open chronicle, the player, and the ledger of what the annals hold. */
public class Crest extends JPanel
{
	private final JLabel title = Ui.label("Codex Annals", Theme.title(), Theme.GOLD_BRIGHT);
	private final JLabel subtitle = Ui.label("Log in to begin your annals", Theme.small(), Theme.TEXT_MUTED);
	private final Ledger entries = new Ledger("Entries");
	private final Ledger days = new Ledger("Days this year");
	private final Ledger hours = new Ledger("Hours this year");

	public Crest()
	{
		super(new BorderLayout(10, 0));
		setOpaque(false);
		setBorder(new EmptyBorder(12, 10, 12, 10));

		JPanel markHolder = new JPanel(new BorderLayout());
		markHolder.setOpaque(false);
		markHolder.add(new Mark(), BorderLayout.NORTH);
		add(markHolder, BorderLayout.WEST);

		JPanel right = new JPanel();
		right.setOpaque(false);
		right.setLayout(new BoxLayout(right, BoxLayout.Y_AXIS));
		title.setAlignmentX(LEFT_ALIGNMENT);
		subtitle.setAlignmentX(LEFT_ALIGNMENT);
		right.add(title);
		right.add(subtitle);
		JPanel ledgers = new JPanel(new GridLayout(3, 1, 0, 2));
		ledgers.setOpaque(false);
		ledgers.setBorder(new EmptyBorder(4, 0, 0, 0));
		ledgers.add(entries);
		ledgers.add(days);
		ledgers.add(hours);
		ledgers.setAlignmentX(LEFT_ALIGNMENT);
		right.add(ledgers);
		add(right, BorderLayout.CENTER);
		update(null, 0, 0, 0, 0);
	}

	/**
	 * @param begunAt when the annals began, or 0 if they have not
	 */
	public void update(String player, long begunAt, int entryCount, int daysThisYear, long playedThisYear)
	{
		title.setText(player != null ? player : "Codex Annals");
		if (begunAt <= 0)
		{
			subtitle.setText(player == null ? "Log in to begin your annals" : "Opening the annals...");
			entries.set("-");
			days.set("-");
			hours.set("-");
			return;
		}
		subtitle.setText("Kept since " + Format.since(begunAt));
		entries.set(Format.number(entryCount));
		days.set(Format.number(daysThisYear));
		hours.set(Format.number(playedThisYear / 3_600_000));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		g.setPaint(new GradientPaint(0, 0, Theme.mix(Theme.INK, Theme.GOLD_DIM, 0.18), 0, h, Theme.INK));
		g.fillRect(0, 0, w, h);
		int y = h - 2;
		g.setPaint(new GradientPaint(0, 0, Theme.alpha(Theme.GOLD, 0), w / 2f, 0, Theme.alpha(Theme.GOLD, 150), true));
		g.drawLine(0, y, w, y);
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(w / 2f, y - 3);
		diamond.lineTo(w / 2f + 3, y);
		diamond.lineTo(w / 2f, y + 3);
		diamond.lineTo(w / 2f - 3, y);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);
		g.dispose();
		super.paintComponent(graphics);
	}

	/** The open chronicle in a gilt ring. */
	private static final class Mark extends JComponent
	{
		private static final int SIZE = 64;

		Mark()
		{
			setPreferredSize(new Dimension(SIZE, SIZE));
			setOpaque(false);
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			Theme.smooth(g);
			g.setPaint(new RadialGradientPaint(SIZE / 2f, SIZE / 2f, SIZE / 2f, new float[]{0f, 1f},
				new Color[]{Theme.alpha(Theme.GOLD, 60), Theme.alpha(Theme.GOLD, 0)}));
			g.fillOval(0, 0, SIZE, SIZE);
			g.setColor(Theme.INK_DEEP);
			g.fillOval(4, 4, SIZE - 8, SIZE - 8);
			g.setColor(Theme.alpha(Theme.GOLD, 180));
			g.drawOval(4, 4, SIZE - 9, SIZE - 9);
			g.setColor(Theme.alpha(Theme.GOLD_DIM, 140));
			g.drawOval(7, 7, SIZE - 15, SIZE - 15);
			Sigil.paint(g, 14, 13, SIZE - 28);
			g.dispose();
		}
	}

	/** One labelled value. */
	private static final class Ledger extends JPanel
	{
		private final JLabel value = Ui.label("-", Theme.small(), Theme.GOLD);

		Ledger(String label)
		{
			super(new BorderLayout());
			setOpaque(false);
			add(Ui.label(label, Theme.small(), Theme.TEXT_MUTED), BorderLayout.WEST);
			add(value, BorderLayout.EAST);
			setPreferredSize(new Dimension(10, 15));
		}

		void set(String text)
		{
			value.setText(text);
		}
	}
}

