package com.codex.annals.ui;

import com.codex.annals.core.Recap;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** One boss, raid or chest across the year: its kills, the game's count after them, and a bar for its share. */
class KillYearRow extends JComponent
{
	private final Recap.KillYear line;
	private final double share;

	KillYearRow(Recap.KillYear line, double share)
	{
		this.line = line;
		this.share = share;
		setOpaque(false);
		setPreferredSize(new Dimension(10, 24));
		setToolTipText(line.getName() + ": " + Format.number(line.getKills()) + " this year"
			+ (line.getKillCount() > 0 ? ", kill count " + Format.number(line.getKillCount()) : ""));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		paint(g, line, share, 0, 0, getWidth());
		g.dispose();
	}

	static void paint(Graphics2D g, Recap.KillYear line, double share, int x, int y, int w)
	{
		g.setFont(Theme.body());
		FontMetrics fm = g.getFontMetrics();
		int base = y + fm.getAscent();
		Path2D mark = new Path2D.Float();
		float my = base - fm.getAscent() / 2f + 1;
		mark.moveTo(x + 3, my - 3);
		mark.lineTo(x + 6, my);
		mark.lineTo(x + 3, my + 3);
		mark.lineTo(x, my);
		mark.closePath();
		g.setColor(Theme.mix(Theme.GOLD_DIM, Theme.KILLS, Math.max(0.2, share)));
		g.fill(mark);

		String count = Format.number(line.getKills());
		String kc = line.getKillCount() > 0 ? "KC " + Format.number(line.getKillCount()) : "";
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		int kcw = kc.isEmpty() ? 0 : small.stringWidth(kc) + 8;
		g.setFont(Theme.body());
		int cw = fm.stringWidth(count);
		Ui.shadowed(g, count, x + w - kcw - cw, base, Theme.KILLS);
		Ui.shadowed(g, Ui.clip(line.getName(), fm, w - kcw - cw - 18), x + 12, base, Theme.TEXT);
		if (!kc.isEmpty())
		{
			g.setFont(Theme.small());
			Ui.shadowed(g, kc, x + w - kcw + 8, base, Theme.TEXT_FAINT);
		}
		int by = base + 4;
		int bw = w - 12;
		g.setColor(Theme.INK_DEEP);
		g.fill(new RoundRectangle2D.Float(x + 12, by, bw, 3, 3, 3));
		g.setColor(Theme.alpha(Theme.KILLS, 200));
		g.fill(new RoundRectangle2D.Float(x + 12, by, (float) Math.max(3, bw * Math.max(0, Math.min(1, share))), 3, 3, 3));
	}
}

package com.codex.annals.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/**
 * The year as twelve gilded tiles, one a month, lit by how many days were played in it.
 * The busiest month burns brightest; hovering names the month and what it held.
 */
class MonthStrip extends JComponent
{
	private static final String LETTERS = "JFMAMJJASOND";
	static final int HEIGHT = 40;

	private final int[] days;
	private final int[] entries;
	private final int current;
	private int hover = -1;

	/**
	 * @param current the month still being lived, 0 for January, or -1 for a finished year
	 */
	MonthStrip(int[] days, int[] entries, int current)
	{
		this.days = days;
		this.entries = entries;
		this.current = current;
		setOpaque(false);
		setPreferredSize(new Dimension(10, HEIGHT));
		setToolTipText("");
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				int index = Math.min(11, Math.max(0, e.getX() * 12 / Math.max(1, getWidth())));
				if (index != hover)
				{
					hover = index;
					repaint();
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = -1;
				repaint();
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	@Override
	public String getToolTipText(MouseEvent e)
	{
		int m = Math.min(11, Math.max(0, e.getX() * 12 / Math.max(1, getWidth())));
		return Format.monthName(m) + ": " + Format.plural(days[m], "day", "days") + " played, "
			+ Format.plural(entries[m], "entry", "entries");
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		paint(g, days, current, hover, 0, 0, getWidth(), getHeight());
		g.dispose();
	}

	/** Draws the strip in a box; the card uses the same drawing. */
	static void paint(Graphics2D g, int[] days, int current, int hover, int x, int y, int w, int h)
	{
		int max = 1;
		for (int d : days)
		{
			max = Math.max(max, d);
		}
		int best = -1;
		for (int m = 0; m < 12 && best < 0; m++)
		{
			best = days[m] == max && days[m] > 0 ? m : -1;
		}
		g.setFont(Theme.small());
		FontMetrics fm = g.getFontMetrics();
		int gap = 3;
		int labelH = fm.getAscent() + 3;
		float cell = (w - gap * 11) / 12f;
		int ch = h - labelH;
		for (int m = 0; m < 12; m++)
		{
			float cx = x + m * (cell + gap);
			double t = days[m] / (double) max;
			RoundRectangle2D tile = new RoundRectangle2D.Float(cx, y, cell, ch, 5, 5);
			Color top;
			Color bottom;
			if (days[m] == 0)
			{
				top = Theme.INK_DEEP;
				bottom = Theme.INK_DEEP;
			}
			else
			{
				Color lit = m == best ? Theme.GOLD_BRIGHT : Theme.mix(Theme.GOLD_DIM, Theme.GOLD, t);
				top = Theme.mix(Theme.CARD, lit, 0.25 + 0.75 * t);
				bottom = Theme.mix(Theme.INK_DEEP, lit, 0.15 + 0.45 * t);
			}
			g.setPaint(new GradientPaint(0, y, top, 0, y + ch, bottom));
			g.fill(tile);
			g.setColor(m == hover ? Theme.alpha(Theme.GOLD_BRIGHT, 200) : m == current ? Theme.alpha(Theme.TEAL, 200)
				: Theme.alpha(Theme.STROKE, days[m] == 0 ? 140 : 90));
			g.draw(tile);
			if (days[m] > 0)
			{
				g.setColor(Theme.alpha(Color.WHITE, 40));
				g.drawLine(Math.round(cx + 3), y + 1, Math.round(cx + cell - 3), y + 1);
			}
			String letter = LETTERS.substring(m, m + 1);
			g.setColor(m == best ? Theme.GOLD : m == hover ? Theme.TEXT : Theme.TEXT_FAINT);
			g.drawString(letter, Math.round(cx + (cell - fm.stringWidth(letter)) / 2), y + h - 1);
		}
	}
}

package com.codex.annals.ui;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import javax.swing.JComponent;

/** A small-caps heading with a gold diamond and a line that fades into the dark. */
public class SectionHeader extends JComponent
{
	private final String text;
	private final String trailing;

	public SectionHeader(String text)
	{
		this(text, null);
	}

	public SectionHeader(String text, String trailing)
	{
		this.text = text.toUpperCase();
		this.trailing = trailing;
		setFont(Theme.small());
		setPreferredSize(new Dimension(10, 20));
		setMinimumSize(new Dimension(10, 20));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
		setAlignmentX(LEFT_ALIGNMENT);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		g.setFont(getFont());
		paint(g, text, trailing, 0, 0, getWidth(), getHeight());
		g.dispose();
	}

	/** Draws a heading in a box; the card uses the same drawing. The font must already be set. */
	static void paint(Graphics2D g, String text, String trailing, int x, int y, int w, int h)
	{
		int mid = y + h / 2 + 2;
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(x + 4, mid - 4);
		diamond.lineTo(x + 8, mid);
		diamond.lineTo(x + 4, mid + 4);
		diamond.lineTo(x, mid);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);

		FontMetrics fm = g.getFontMetrics();
		int textX = x + 13;
		int baseline = mid + fm.getAscent() / 2 - 1;
		g.setColor(Theme.GOLD);
		g.drawString(text, textX, baseline);

		int lineStart = textX + fm.stringWidth(text) + 6;
		int lineEnd = x + w;
		if (trailing != null && !trailing.isEmpty())
		{
			int tw = fm.stringWidth(trailing);
			lineEnd = x + w - tw - 6;
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(trailing, x + w - tw, baseline);
		}
		if (lineEnd > lineStart)
		{
			g.setPaint(new GradientPaint(lineStart, 0, Theme.alpha(Theme.GOLD, 110), lineEnd, 0, Theme.alpha(Theme.GOLD, 0)));
			g.drawLine(lineStart, mid, lineEnd, mid);
		}
	}
}

package com.codex.annals.ui;

import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import java.util.function.IntConsumer;
import javax.swing.JComponent;

/**
 * Tabs drawn as one engraved strip: the chosen segment is lit from below by a
 * gold glow, the rest sit quietly in the ink.
 */
public class Segmented extends JComponent
{
	private final String[] labels;
	private final boolean large;
	private final Animator slide = new Animator(this);
	private int selected;
	private int hover = -1;
	private IntConsumer listener;

	public Segmented(boolean large, String... labels)
	{
		this.labels = labels;
		this.large = large;
		setFont(large ? Theme.title() : Theme.small());
		int h = large ? 28 : 22;
		setPreferredSize(new Dimension(10, h));
		setMinimumSize(new Dimension(10, h));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, h));
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				int index = indexAt(e.getX());
				if (index != hover)
				{
					hover = index;
					repaint();
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = -1;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				setSelected(indexAt(e.getX()), true);
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	public void onChange(IntConsumer listener)
	{
		this.listener = listener;
	}

	public int getSelected()
	{
		return selected;
	}

	public void setSelected(int index, boolean notify)
	{
		if (index < 0 || index >= labels.length)
		{
			return;
		}
		boolean changed = index != selected;
		selected = index;
		slide.set(index, true);
		repaint();
		if (changed && notify && listener != null)
		{
			listener.accept(index);
		}
	}

	private int indexAt(int x)
	{
		int w = Math.max(1, getWidth());
		return Math.max(0, Math.min(labels.length - 1, x * labels.length / w));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		float seg = w / (float) labels.length;

		RoundRectangle2D strip = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, 8, 8);
		g.setColor(Theme.INK_DEEP);
		g.fill(strip);

		float x = (float) (slide.get() * seg);
		RoundRectangle2D lit = new RoundRectangle2D.Float(x + 2, 2, seg - 4, h - 4, 6, 6);
		g.setPaint(new GradientPaint(0, 2, Theme.CARD_TOP, 0, h, Theme.mix(Theme.CARD_TOP, Theme.GOLD_DIM, 0.35)));
		g.fill(lit);
		g.setColor(Theme.alpha(Theme.GOLD, 120));
		g.draw(lit);
		g.setColor(Theme.GOLD_BRIGHT);
		g.fillRect(Math.round(x + seg * 0.3f), h - 4, Math.round(seg * 0.4f), 1);

		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		for (int i = 0; i < labels.length; i++)
		{
			int tx = Math.round(i * seg + (seg - fm.stringWidth(labels[i])) / 2);
			int ty = (h + fm.getAscent()) / 2 - (large ? 2 : 1);
			java.awt.Color color = i == selected ? Theme.GOLD_BRIGHT : i == hover ? Theme.TEXT : Theme.TEXT_MUTED;
			Ui.shadowed(g, labels[i], tx, ty, color);
		}
		g.setColor(Theme.STROKE_SOFT);
		g.draw(strip);
		g.dispose();
	}
}

package com.codex.annals.ui;

import java.awt.BasicStroke;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;

/** Annals' mark: an open chronicle on a gilt binding, a ribbon marking the page, a teal star above. */
public final class Sigil
{
	private Sigil()
	{
	}

	public static BufferedImage icon(int size)
	{
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		Theme.smooth(g);
		paint(g, 0, 0, size);
		g.dispose();
		return image;
	}

	/** Draws the mark in a size by size box. */
	public static void paint(Graphics2D g, float x, float y, float size)
	{
		float s = size / 16f;
		BasicStroke edge = new BasicStroke(Math.max(0.6f, 0.55f * s), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);

		// The binding, a little wider than the pages.
		Path2D cover = new Path2D.Float();
		cover.moveTo(x + 0.4f * s, y + 6.2f * s);
		cover.lineTo(x + 0.4f * s, y + 13.6f * s);
		cover.quadTo(x + 4.4f * s, y + 12.6f * s, x + 8 * s, y + 14.6f * s);
		cover.quadTo(x + 11.6f * s, y + 12.6f * s, x + 15.6f * s, y + 13.6f * s);
		cover.lineTo(x + 15.6f * s, y + 6.2f * s);
		cover.closePath();
		g.setPaint(new GradientPaint(x, y + 6 * s, Theme.GOLD, x, y + 15 * s, Theme.GOLD_DIM));
		g.fill(cover);
		g.setColor(Theme.INK_DEEP);
		g.setStroke(edge);
		g.draw(cover);

		// Two pages curving up from the spine.
		for (int side = -1; side <= 1; side += 2)
		{
			float sx = side;
			Path2D page = new Path2D.Float();
			page.moveTo(x + 8 * s, y + 13.4f * s);
			page.quadTo(x + (8 + sx * 3.4f) * s, y + 11.4f * s, x + (8 + sx * 6.8f) * s, y + 12.4f * s);
			page.lineTo(x + (8 + sx * 6.8f) * s, y + 5.2f * s);
			page.quadTo(x + (8 + sx * 3.4f) * s, y + 4.2f * s, x + 8 * s, y + 6 * s);
			page.closePath();
			g.setPaint(new GradientPaint(x + 8 * s, y, Theme.mix(Theme.TEXT, Theme.GOLD_BRIGHT, 0.35),
				x + (8 + sx * 7) * s, y, Theme.mix(Theme.GOLD_BRIGHT, Theme.GOLD_DIM, 0.35)));
			g.fill(page);
			g.setColor(Theme.INK_DEEP);
			g.draw(page);

			// Lines of writing on each page.
			g.setColor(Theme.alpha(Theme.INK_DEEP, 150));
			for (int line = 0; line < 3; line++)
			{
				float ly = 7.4f + line * 1.6f;
				float from = 8 + sx * 1.4f;
				float to = 8 + sx * (line == 2 ? 4.2f : 5.6f);
				g.drawLine(Math.round(x + from * s), Math.round(y + ly * s), Math.round(x + to * s), Math.round(y + (ly - 0.3f) * s));
			}
		}

		// The ribbon, hanging from the spine below the binding.
		Path2D ribbon = new Path2D.Float();
		ribbon.moveTo(x + 9.2f * s, y + 9 * s);
		ribbon.lineTo(x + 10.6f * s, y + 9 * s);
		ribbon.lineTo(x + 10.6f * s, y + 15.8f * s);
		ribbon.lineTo(x + 9.9f * s, y + 15 * s);
		ribbon.lineTo(x + 9.2f * s, y + 15.8f * s);
		ribbon.closePath();
		g.setPaint(new GradientPaint(x, y + 9 * s, Theme.BLOOD, x, y + 16 * s, Theme.BLOOD_DEEP));
		g.fill(ribbon);

		// A teal star over the book, for the moment being written down.
		float cx = x + 8 * s;
		float cy = y + 2.2f * s;
		float r = 2.2f * s;
		float w = 0.55f * s;
		Path2D star = new Path2D.Float();
		star.moveTo(cx, cy - r);
		star.lineTo(cx + w, cy - w);
		star.lineTo(cx + r, cy);
		star.lineTo(cx + w, cy + w);
		star.lineTo(cx, cy + r);
		star.lineTo(cx - w, cy + w);
		star.lineTo(cx - r, cy);
		star.lineTo(cx - w, cy - w);
		star.closePath();
		g.setColor(Theme.alpha(Theme.TEAL, 90));
		g.fill(new java.awt.geom.Ellipse2D.Float(cx - r * 0.8f, cy - r * 0.8f, r * 1.6f, r * 1.6f));
		g.setColor(Theme.TEAL);
		g.fill(star);
	}
}

package com.codex.annals.ui;

import com.codex.annals.core.Recap;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;

/** One skill's year: its icon and name, the levels it rose through, the experience, and its share of the whole. */
class SkillYearRow extends JComponent
{
	private final Recap.SkillYear line;
	private final BufferedImage icon;
	private final double share;

	SkillYearRow(Recap.SkillYear line, BufferedImage icon, double share)
	{
		this.line = line;
		this.icon = icon;
		this.share = share;
		setOpaque(false);
		setPreferredSize(new Dimension(10, 30));
		setToolTipText(line.getSkill() + ": " + Format.number(line.getGained()) + " xp this year");
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		paint(g, line, icon, share, 0, 0, getWidth());
		g.dispose();
	}

	/** Draws the row at a place and width; the card uses the same drawing. */
	static void paint(Graphics2D g, Recap.SkillYear line, BufferedImage icon, double share, int x, int y, int w)
	{
		int iconBox = 20;
		if (icon != null)
		{
			double scale = Math.min(1, iconBox / (double) Math.max(icon.getWidth(), icon.getHeight()));
			int iw = (int) Math.round(icon.getWidth() * scale);
			int ih = (int) Math.round(icon.getHeight() * scale);
			g.drawImage(icon, x + (iconBox - iw) / 2, y + 2 + (iconBox - ih) / 2, iw, ih, null);
		}
		int tx = x + iconBox + 6;
		g.setFont(Theme.body());
		FontMetrics fm = g.getFontMetrics();
		int base = y + fm.getAscent() + 1;
		String gained = Format.xp(line.getGained());
		int gw = fm.stringWidth(gained);
		Ui.shadowed(g, gained, x + w - gw, base, Theme.XP);
		String levels = line.getEndLevel() > line.getStartLevel() ? line.getStartLevel() + " > " + line.getEndLevel() : String.valueOf(line.getEndLevel());
		int nameRoom = w - (tx - x) - gw - 8;
		String name = Ui.clip(line.getSkill(), fm, nameRoom);
		Ui.shadowed(g, name, tx, base, Theme.TEXT);
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		int lx = tx + fm.stringWidth(name) + 6;
		if (lx + small.stringWidth(levels) < x + w - gw - 6)
		{
			Ui.shadowed(g, levels, lx, base, line.getEndLevel() > line.getStartLevel() ? Theme.GREEN : Theme.TEXT_FAINT);
		}

		int by = y + 22;
		int bw = w - (tx - x);
		RoundRectangle2D track = new RoundRectangle2D.Float(tx, by, bw, 4, 4, 4);
		g.setColor(Theme.INK_DEEP);
		g.fill(track);
		float fill = (float) Math.max(4, bw * Math.max(0, Math.min(1, share)));
		g.setPaint(new GradientPaint(tx, 0, Theme.mix(Theme.TEAL, Theme.INK, 0.35), tx + bw, 0, Theme.TEAL));
		g.fill(new RoundRectangle2D.Float(tx, by, fill, 4, 4, 4));
	}
}

package com.codex.annals.ui;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.LayoutManager;
import java.awt.Rectangle;
import javax.swing.JPanel;
import javax.swing.Scrollable;
import javax.swing.border.EmptyBorder;

/**
 * A vertical stack where every child spans the full width at its preferred height.
 * It tracks the viewport width so nothing ever scrolls sideways in the side panel.
 */
public class StackPanel extends JPanel implements Scrollable
{
	public StackPanel(int gap, int pad)
	{
		super(new StackLayout(gap));
		setOpaque(false);
		setBorder(new EmptyBorder(pad, pad, pad, pad));
	}

	public StackPanel space(int height)
	{
		JPanel spacer = new JPanel();
		spacer.setOpaque(false);
		spacer.setPreferredSize(new Dimension(1, height));
		add(spacer);
		return this;
	}

	@Override
	public Dimension getPreferredScrollableViewportSize()
	{
		return getPreferredSize();
	}

	@Override
	public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return 16;
	}

	@Override
	public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return Math.max(16, visibleRect.height - 32);
	}

	@Override
	public boolean getScrollableTracksViewportWidth()
	{
		return true;
	}

	@Override
	public boolean getScrollableTracksViewportHeight()
	{
		return false;
	}

	static final class StackLayout implements LayoutManager
	{
		private final int gap;

		StackLayout(int gap)
		{
			this.gap = gap;
		}

		@Override
		public void addLayoutComponent(String name, Component comp)
		{
		}

		@Override
		public void removeLayoutComponent(Component comp)
		{
		}

		@Override
		public Dimension preferredLayoutSize(Container parent)
		{
			Insets in = parent.getInsets();
			int width = 0;
			int height = 0;
			int visible = 0;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				Dimension d = c.getPreferredSize();
				width = Math.max(width, d.width);
				height += d.height;
				visible++;
			}
			height += Math.max(0, visible - 1) * gap;
			return new Dimension(width + in.left + in.right, height + in.top + in.bottom);
		}

		@Override
		public Dimension minimumLayoutSize(Container parent)
		{
			return preferredLayoutSize(parent);
		}

		@Override
		public void layoutContainer(Container parent)
		{
			Insets in = parent.getInsets();
			int width = parent.getWidth() - in.left - in.right;
			int y = in.top;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				int h = c.getPreferredSize().height;
				c.setBounds(in.left, y, width, h);
				y += h + gap;
			}
		}
	}
}

package com.codex.annals.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A small engraved tablet: a big number, its label, and a quiet line of context. */
class StatTile extends JComponent
{
	private final String value;
	private final String label;
	private final String note;
	private final Color color;

	StatTile(String value, String label, String note, Color color)
	{
		this.value = value;
		this.label = label;
		this.note = note;
		this.color = color;
		setPreferredSize(new Dimension(10, 54));
		setOpaque(false);
		setToolTipText(note == null || note.isEmpty() ? label : label + ": " + note);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		paint(g, value, label, note, color, 0, 0, getWidth(), getHeight());
		g.dispose();
	}

	/** Draws a tablet in a box; the card uses the same drawing. */
	static void paint(Graphics2D g, String value, String label, String note, Color color, int x, int y, int w, int h)
	{
		RoundRectangle2D shape = new RoundRectangle2D.Float(x + 0.5f, y + 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(x, y, Theme.CARD_TOP, x, y + h, Theme.CARD));
		g.fill(shape);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(shape);
		g.setColor(Theme.alpha(color, 160));
		g.fillRect(x + Theme.RADIUS, y + 1, w - Theme.RADIUS * 2, 1);

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(label.toUpperCase(), x + 8, y + 6 + small.getAscent());

		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		Ui.shadowed(g, Ui.clip(value, bold, w - 16), x + 8, y + 8 + small.getHeight() + bold.getAscent(), color);
		if (note != null && !note.isEmpty())
		{
			g.setFont(Theme.small());
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(Ui.clip(note, small, w - 16), x + 8, y + h - 6);
		}
	}
}

package com.codex.annals.ui;

import com.codex.annals.core.Entry;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import net.runelite.client.ui.FontManager;

/**
 * The Codex look: warm ink, aged gold and a single arcane teal, drawn with the
 * game's own fonts so the panel reads as part of Gielinor rather than a web page.
 * Annals gives each chapter its own colour, so a line on the timeline says what it is before it is read:
 * skills green, feats blue, loot gold, bosses ember and pets violet.
 */
public final class Theme
{
	public static final Color INK = new Color(23, 20, 16);
	public static final Color INK_DEEP = new Color(16, 14, 11);
	public static final Color CARD = new Color(34, 30, 24);
	public static final Color CARD_TOP = new Color(42, 37, 29);
	public static final Color CARD_HOVER = new Color(48, 42, 33);
	public static final Color STROKE = new Color(66, 56, 42);
	public static final Color STROKE_SOFT = new Color(48, 41, 32);

	public static final Color GOLD = new Color(214, 178, 106);
	public static final Color GOLD_BRIGHT = new Color(246, 214, 144);
	public static final Color GOLD_DIM = new Color(132, 108, 66);
	public static final Color TEAL = new Color(96, 184, 170);
	public static final Color GREEN = new Color(130, 196, 108);
	public static final Color EMBER = new Color(222, 134, 86);
	public static final Color BLOCKED = new Color(176, 92, 84);
	public static final Color BLOOD = new Color(204, 70, 60);
	public static final Color BLOOD_DEEP = new Color(120, 32, 28);
	public static final Color VIOLET = new Color(176, 132, 222);

	public static final Color TEXT = new Color(234, 224, 202);
	public static final Color TEXT_MUTED = new Color(160, 148, 126);
	public static final Color TEXT_FAINT = new Color(110, 100, 84);

	public static final int RADIUS = 10;
	public static final int GUTTER = 8;

	private Theme()
	{
	}

	public static Font title()
	{
		return FontManager.getRunescapeBoldFont();
	}

	public static Font body()
	{
		return FontManager.getRunescapeFont();
	}

	public static Font small()
	{
		return FontManager.getRunescapeSmallFont();
	}

	public static Color alpha(Color c, int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}

	public static Color mix(Color a, Color b, double t)
	{
		t = Math.max(0, Math.min(1, t));
		return new Color(
			(int) Math.round(a.getRed() + (b.getRed() - a.getRed()) * t),
			(int) Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * t),
			(int) Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * t),
			(int) Math.round(a.getAlpha() + (b.getAlpha() - a.getAlpha()) * t));
	}

	/** Progress colour: ember when just begun, gold through the middle, green when nearly there. */
	public static Color progressColor(double progress)
	{
		if (progress >= 1)
		{
			return GREEN;
		}
		if (progress < 0.5)
		{
			return mix(EMBER, GOLD, progress * 2);
		}
		return mix(GOLD, TEAL, (progress - 0.5) * 2);
	}

	/** Item quantities in the game's own colours: yellow, white from 100K, green from 10M. */
	public static final Color QTY_YELLOW = new Color(255, 255, 0);
	public static final Color QTY_WHITE = new Color(255, 255, 255);
	public static final Color QTY_GREEN = new Color(0, 255, 128);

	public static final Color XP = TEAL;
	public static final Color FEAT = new Color(150, 170, 230);
	public static final Color KILLS = EMBER;

	/** The colour of a kind of entry. */
	public static Color entry(Entry.Kind kind)
	{
		switch (kind)
		{
			case PET:
				return VIOLET;
			case MAX:
			case TOTAL:
				return GOLD_BRIGHT;
			case COLLECTION:
				return TEAL;
			case DROP:
			case CLUE:
				return GOLD;
			case QUEST:
			case DIARY:
			case TASK:
				return FEAT;
			case BOSS:
				return EMBER;
			case LEVEL:
			case XP:
			case COMBAT:
				return GREEN;
			default:
				return GOLD_DIM;
		}
	}

	/** Smooth shapes, but the pixel fonts stay crisp. */
	public static void smooth(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
	}
}

package com.codex.annals.ui;

import com.codex.annals.core.Annals;
import com.codex.annals.core.Baseline;
import com.codex.annals.core.Entry;
import com.codex.annals.core.Timeline;
import java.awt.BorderLayout;
import java.awt.FlowLayout;
import java.time.Instant;
import java.time.LocalDate;
import java.time.YearMonth;
import java.time.ZoneId;
import java.util.List;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JPanel;

/**
 * The Timeline tab: every entry of the account's history, newest first, in chapters by month,
 * ending with the prologue: where the account stood the day the annals began.
 */
final class TimelineView
{
	static final String[] CHAPTERS = {"All", "Skills", "Feats", "Loot", "Bosses"};

	private TimelineView()
	{
	}

	/**
	 * @param limit how many rows to show before the button that shows more
	 * @param more called to show more rows
	 */
	static JComponent build(Annals annals, ZoneId zone, Segmented chapters, int limit, Runnable more,
		ItemIcons items, Icons icons, Runnable onLoaded)
	{
		StackPanel stack = new StackPanel(6, 8);
		stack.add(chapters);
		if (annals == null || !annals.isBegun())
		{
			stack.add(Views.note("The annals are waiting", "Log in and Codex Annals begins your account's history: every level, quest, diary, "
				+ "collection log slot, pet, first kill and notable drop, written down with its day. Each year becomes a Year in Gielinor card to share."));
			return stack;
		}

		Entry.Chapter chapter = Entry.Chapter.values()[chapters.getSelected()];
		List<Timeline.Row> rows = Timeline.rows(annals.getEntries(), chapter, zone);
		if (rows.isEmpty())
		{
			stack.add(Views.note("Nothing here yet", "Entries of this kind are written down as they happen. Keep playing and this chapter fills."));
			return stack;
		}

		int shown = Math.min(limit, rows.size());
		int i = 0;
		while (i < shown)
		{
			YearMonth month = YearMonth.from(rows.get(i).getDate());
			int end = i;
			while (end < rows.size() && YearMonth.from(rows.get(end).getDate()).equals(month))
			{
				end++;
			}
			int count = 0;
			for (int k = i; k < end; k++)
			{
				count += Math.max(1, rows.get(k).getFolded());
			}
			stack.add(new SectionHeader(Format.month(rows.get(i).getDate()), Format.plural(count, "entry", "entries")));
			JPanel run = new JPanel();
			run.setOpaque(false);
			run.setLayout(new BoxLayout(run, BoxLayout.Y_AXIS));
			int stop = Math.min(end, shown);
			for (int k = i; k < stop; k++)
			{
				Timeline.Row row = rows.get(k);
				EntryRow line = new EntryRow(row.getEntry(), row.getDate(), Views.icon(row.getEntry(), items, icons, onLoaded), k == i, k == stop - 1);
				line.setAlignmentX(JComponent.LEFT_ALIGNMENT);
				run.add(line);
			}
			stack.add(run);
			i = stop;
		}

		if (shown < rows.size())
		{
			JPanel holder = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 0));
			holder.setOpaque(false);
			holder.add(new CodexButton("Show older entries", false, more));
			stack.add(holder);
		}
		else if (chapter == Entry.Chapter.ALL && annals.getBaseline() != null)
		{
			stack.add(new SectionHeader("Prologue", Format.since(annals.getBegunAt())));
			stack.add(prologue(annals.getBaseline(), dayOf(annals.getBegunAt(), zone)));
		}
		return stack;
	}

	private static LocalDate dayOf(long at, ZoneId zone)
	{
		return Instant.ofEpochMilli(at).atZone(zone).toLocalDate();
	}

	/** Where the account stood when the annals began, since nothing before can be dated. */
	static Card prologue(Baseline b, LocalDate day)
	{
		Card card = new Card(new BorderLayout(0, 4));
		card.accent(Theme.GOLD_DIM);
		card.add(Ui.label("Before the annals", Theme.body(), Theme.GOLD), BorderLayout.NORTH);
		StringBuilder text = new StringBuilder("On " + Format.shortDay(day) + " " + day.getYear() + " the account stood at total level "
			+ Format.number(b.getTotalLevel()) + " with " + Format.amount(b.getTotalXp()) + " experience, combat level " + b.getCombat());
		if (b.getQuestsTotal() > 0)
		{
			text.append(", and ").append(b.getQuestsDone()).append(" of ").append(b.getQuestsTotal()).append(" quests done");
		}
		text.append('.');
		List<String> maxed = b.getMaxed();
		if (!maxed.isEmpty())
		{
			text.append(maxed.size() == 1 ? " Already 99: " : " Already " + maxed.size() + " skills at 99: ").append(String.join(", ", maxed)).append('.');
		}
		text.append(" Everything above was written down as it happened.");
		card.add(Ui.wrapped(text.toString(), Theme.small(), Theme.TEXT_MUTED, Views.WIDTH - 30), BorderLayout.CENTER);
		return card;
	}
}

package com.codex.annals.ui;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import javax.swing.JLabel;

/** Small helpers shared by the panel's components. */
public final class Ui
{
	private Ui()
	{
	}

	public static JLabel label(String text, Font font, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(font);
		label.setForeground(color);
		return label;
	}

	/**
	 * A label that wraps inside the side panel's narrow width. Swing's HTML renderer
	 * treats CSS pixels as points, so the width is converted to keep it in screen pixels.
	 */
	public static JLabel wrapped(String text, Font font, Color color, int width)
	{
		int css = Math.round(width * 0.75f);
		return label("<html><div style='width:" + css + "px'>" + escape(text) + "</div></html>", font, color);
	}

	public static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Lets a clickable card keep its hover and click while the pointer is over its children. */
	static void forwardMouse(Container root, MouseAdapter adapter)
	{
		for (Component child : root.getComponents())
		{
			child.addMouseListener(adapter);
			if (child instanceof Container)
			{
				forwardMouse((Container) child, adapter);
			}
		}
	}

	/** Text with the one pixel black shadow the game puts under its own lettering. */
	public static void shadowed(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	/** Cuts text to fit a width, ending it with an ellipsis. */
	public static String clip(String text, java.awt.FontMetrics fm, int width)
	{
		if (text == null)
		{
			return "";
		}
		if (fm.stringWidth(text) <= width)
		{
			return text;
		}
		int end = text.length();
		while (end > 0 && fm.stringWidth(text.substring(0, end) + "...") > width)
		{
			end--;
		}
		return text.substring(0, end) + "...";
	}
}

package com.codex.annals.ui;

import com.codex.annals.core.Entry;
import java.awt.BorderLayout;
import java.awt.image.BufferedImage;

/** What every tab shares: the width the side panel lays out to, and the quiet note card. */
final class Views
{
	static final int WIDTH = 200;

	private Views()
	{
	}

	static Card note(String title, String text)
	{
		Card card = new Card(new BorderLayout(0, 4));
		card.accent(Theme.GOLD_DIM);
		card.add(Ui.label(title, Theme.body(), Theme.GOLD), BorderLayout.NORTH);
		card.add(Ui.wrapped(text, Theme.small(), Theme.TEXT_MUTED, WIDTH - 30), BorderLayout.CENTER);
		return card;
	}

	/** The picture an entry shows: its item, else its skill, else none. */
	static BufferedImage icon(Entry e, ItemIcons items, Icons icons, Runnable onLoaded)
	{
		if (e.getItemId() > 0 && items != null)
		{
			return items.icon(e.getItemId(), onLoaded);
		}
		if (e.getSkill() != null && icons != null)
		{
			return icons.skill(e.getSkill());
		}
		return null;
	}
}

package com.codex.annals.ui;

import com.codex.annals.core.Entry;
import com.codex.annals.core.Recap;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;

/**
 * The Year in Gielinor card: a whole year on one gilt-framed page, drawn at twice the panel's
 * scale so the game's pixel fonts stay crisp wherever it is posted.
 */
public final class YearCard
{
	static final int WIDTH = 360;
	static final int SCALE = 2;
	private static final int PAD = 20;
	private static final int SKILLS = 4;
	private static final int BOSSES = 4;
	private static final int HIGHLIGHTS = 4;

	private YearCard()
	{
	}

	/** Renders the card; icons still loading are left out and onLoaded runs when one arrives. */
	public static BufferedImage render(Recap r, boolean showName, ItemIcons items, Icons skills, Runnable onLoaded)
	{
		BufferedImage scratch = new BufferedImage(WIDTH, 2000, BufferedImage.TYPE_INT_ARGB);
		Graphics2D sg = scratch.createGraphics();
		int height = content(sg, r, showName, items, skills, onLoaded);
		sg.dispose();

		BufferedImage image = new BufferedImage(WIDTH * SCALE, height * SCALE, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.scale(SCALE, SCALE);
		Theme.smooth(g);
		frame(g, height);
		content(g, r, showName, items, skills, onLoaded);
		g.dispose();
		return image;
	}

	private static void frame(Graphics2D g, int h)
	{
		int w = WIDTH;
		RoundRectangle2D page = new RoundRectangle2D.Float(0, 0, w, h, 18, 18);
		g.setPaint(new GradientPaint(0, 0, Theme.mix(Theme.INK, Theme.CARD_TOP, 0.5), 0, h, Theme.INK_DEEP));
		g.fill(page);
		g.setClip(page);
		g.setPaint(new RadialGradientPaint(w / 2f, 70, w * 0.75f, new float[]{0f, 1f},
			new Color[]{Theme.alpha(Theme.GOLD, 58), Theme.alpha(Theme.GOLD, 0)}));
		g.fillRect(0, 0, w, h);

		// A faint grain, the same every time, so the page reads as vellum rather than a flat fill.
		Random grain = new Random(11);
		for (int i = 0; i < w * h / 26; i++)
		{
			g.setColor(Theme.alpha(grain.nextBoolean() ? Theme.GOLD_BRIGHT : Color.BLACK, 6 + grain.nextInt(8)));
			g.fillRect(grain.nextInt(w), grain.nextInt(h), 1, 1);
		}

		Composite old = g.getComposite();
		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.04f));
		Sigil.paint(g, w - 196, h - 206, 180);
		g.setComposite(old);
		g.setClip(null);

		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(Theme.GOLD, 190));
		g.draw(new RoundRectangle2D.Float(4.5f, 4.5f, w - 9, h - 9, 14, 14));
		g.setColor(Theme.alpha(Theme.GOLD_DIM, 120));
		g.draw(new RoundRectangle2D.Float(8.5f, 8.5f, w - 17, h - 17, 10, 10));
		float[][] corners = {{14, 14}, {w - 14, 14}, {14, h - 14}, {w - 14, h - 14}};
		for (float[] c : corners)
		{
			diamond(g, c[0], c[1], 3.5f, Theme.GOLD);
		}
	}

	/** Lays out and draws everything inside the frame; returns the page height it needs. */
	private static int content(Graphics2D g, Recap r, boolean showName, ItemIcons items, Icons skills, Runnable onLoaded)
	{
		Theme.smooth(g);
		int x = PAD;
		int w = WIDTH - PAD * 2;
		int y = PAD + 4;

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		Sigil.paint(g, x, y - 2, 14);
		g.setColor(Theme.GOLD);
		g.drawString("CODEX ANNALS", x + 19, y + small.getAscent() - 1);
		String kind = "A YEAR IN GIELINOR";
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(kind, x + w - small.stringWidth(kind), y + small.getAscent() - 1);
		y += small.getHeight() + 10;

		// The year itself, large, in gilt.
		Font huge = Theme.title().deriveFont(Theme.title().getSize2D() * 4);
		g.setFont(huge);
		FontMetrics hm = g.getFontMetrics();
		String year = String.valueOf(r.getYear());
		int yw = hm.stringWidth(year);
		int yx = x + (w - yw) / 2;
		int base = y + hm.getAscent() - 12;
		g.setColor(Color.BLACK);
		g.drawString(year, yx + 2, base + 2);
		g.setPaint(new GradientPaint(0, base - hm.getAscent() + 14, Theme.GOLD_BRIGHT, 0, base, Theme.GOLD_DIM));
		g.drawString(year, yx, base);
		ornament(g, x, yx - 10, base - hm.getAscent() / 2 + 6);
		ornament(g, yx + yw + 10, x + w, base - hm.getAscent() / 2 + 6);
		y = base + 8;

		if (showName && r.getPlayer() != null)
		{
			g.setFont(Theme.title());
			FontMetrics bold = g.getFontMetrics();
			centered(g, Ui.clip(r.getPlayer(), bold, w), x, w, y + bold.getAscent(), Theme.TEXT);
			y += bold.getHeight();
		}
		g.setFont(Theme.body());
		FontMetrics body = g.getFontMetrics();
		centered(g, Ui.clip(r.getHeadline(), body, w), x, w, y + body.getAscent(), Theme.GOLD_BRIGHT);
		y += body.getHeight();
		g.setFont(Theme.small());
		g.setColor(Theme.TEXT_MUTED);
		String when = Format.hours(r.getPlayedMs()) + " across " + Format.plural(r.getDaysPlayed(), "day", "days");
		g.drawString(when, x + (w - small.stringWidth(when)) / 2, y + small.getAscent());
		y += small.getHeight() + 8;
		rule(g, x, y, w);
		y += 10;

		int tileW = (w - 12) / 3;
		int tileH = 54;
		StatTile.paint(g, Format.number(r.getDaysPlayed()), "Days played",
			r.getLongestStreak() > 1 ? "best run " + r.getLongestStreak() : "", Theme.TEAL, x, y, tileW, tileH);
		StatTile.paint(g, "+" + Format.number(r.getLevelsGained()), "Levels", Format.xp(r.getXpGained()) + " xp", Theme.GREEN,
			x + tileW + 6, y, tileW, tileH);
		List<Recap.KillYear> bosses = r.getBosses();
		StatTile.paint(g, Format.number(r.getKills()), "Boss kills", bosses.isEmpty() ? "" : bosses.get(0).getName(), Theme.KILLS,
			x + (tileW + 6) * 2, y, w - (tileW + 6) * 2, tileH);
		y += tileH + 8;

		y = tallies(g, r, x, y, w) + 10;

		header(g, "Months", r.busiestMonth() >= 0 ? "busiest " + Format.monthName(r.busiestMonth()) : null, x, y, w);
		y += 24;
		MonthStrip.paint(g, r.getMonthDays(), -1, -1, x, y, w, MonthStrip.HEIGHT);
		y += MonthStrip.HEIGHT + 10;

		List<Recap.SkillYear> skillLines = r.getSkills();
		boolean twoColumns = !skillLines.isEmpty() && !bosses.isEmpty();
		int colW = twoColumns ? (w - 14) / 2 : w;
		int top = y;
		int left = top;
		if (!skillLines.isEmpty())
		{
			header(g, "Skills", null, x, top, colW);
			left += 24;
			long most = skillLines.get(0).getGained();
			for (int i = 0; i < skillLines.size() && i < SKILLS; i++)
			{
				Recap.SkillYear line = skillLines.get(i);
				SkillYearRow.paint(g, line, skills == null ? null : skills.skill(line.getSkill()), line.getGained() / (double) most, x, left, colW);
				left += 30;
			}
		}
		int right = top;
		if (!bosses.isEmpty())
		{
			int bx = twoColumns ? x + colW + 14 : x;
			int by = twoColumns ? top : left + 4;
			header(g, "Bosses", null, bx, by, colW);
			by += 24;
			int most = bosses.get(0).getKills();
			for (int i = 0; i < bosses.size() && i < BOSSES; i++)
			{
				KillYearRow.paint(g, bosses.get(i), bosses.get(i).getKills() / (double) most, bx, by, colW);
				by += 30;
			}
			right = by;
		}
		y = Math.max(left, right) + 4;

		List<Entry> highlights = new ArrayList<>(r.getHighlights());
		if (!highlights.isEmpty())
		{
			header(g, "Highlights", null, x, y, w);
			y += 24;
			for (int i = 0; i < highlights.size() && i < HIGHLIGHTS; i++)
			{
				Entry e = highlights.get(i);
				Color color = Theme.entry(e.getKind());
				EntryRow.node(g, e.getKind(), x + 6, y + 7, color);
				int tx = x + 20;
				int edge = x + w;
				BufferedImage icon = Views.icon(e, items, skills, onLoaded);
				if (icon != null)
				{
					int box = 26;
					double scale = Math.min(1, box / (double) Math.max(icon.getWidth(), icon.getHeight()));
					int iw = (int) Math.round(icon.getWidth() * scale);
					int ih = (int) Math.round(icon.getHeight() * scale);
					g.drawImage(icon, edge - box + (box - iw) / 2, y - 4 + (box - ih) / 2, iw, ih, null);
					edge -= box + 6;
				}
				String date = Format.shortDay(java.time.Instant.ofEpochMilli(e.getAt()).atZone(java.time.ZoneId.systemDefault()).toLocalDate());
				g.setFont(Theme.body());
				FontMetrics fm = g.getFontMetrics();
				Ui.shadowed(g, Ui.clip(e.getTitle(), fm, edge - tx), tx, y + fm.getAscent() - 2, Theme.mix(Theme.TEXT, color, 0.3));
				g.setFont(Theme.small());
				String detail = EntryRow.detail(e);
				String line = detail == null ? date : date + ", " + detail;
				g.setColor(Theme.TEXT_MUTED);
				g.drawString(Ui.clip(line, small, edge - tx), tx, y + fm.getAscent() + small.getAscent());
				y += 32;
			}
		}

		y += 2;
		rule(g, x, y, w);
		y += 8;
		g.setFont(Theme.small());
		g.setColor(Theme.TEXT_FAINT);
		g.drawString("Codex Annals for RuneLite", x, y + small.getAscent());
		String since = "Kept since " + Format.since(r.getBegunAt());
		g.drawString(since, x + w - small.stringWidth(since), y + small.getAscent());
		y += small.getHeight();
		return y + PAD;
	}

	/** A row of small medallions for the year's quests, diaries, log slots, pets and clues. */
	private static int tallies(Graphics2D g, Recap r, int x, int y, int w)
	{
		String[][] items = {
			{Format.number(r.getQuests()), r.getQuests() == 1 ? "quest" : "quests"},
			{Format.number(r.getDiaries()), r.getDiaries() == 1 ? "diary" : "diaries"},
			{Format.number(r.getCollection()), "log slots"},
			{Format.number(r.getPets()), r.getPets() == 1 ? "pet" : "pets"},
			{Format.number(r.getClues()), "clues"},
		};
		Color[] colors = {Theme.FEAT, Theme.FEAT, Theme.TEAL, Theme.VIOLET, Theme.GOLD};
		int gap = 4;
		float cell = (w - gap * (items.length - 1)) / (float) items.length;
		int h = 34;
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		for (int i = 0; i < items.length; i++)
		{
			float cx = x + i * (cell + gap);
			RoundRectangle2D shape = new RoundRectangle2D.Float(cx + 0.5f, y + 0.5f, cell - 1, h - 1, 8, 8);
			g.setColor(Theme.alpha(Theme.INK_DEEP, 200));
			g.fill(shape);
			g.setColor(Theme.alpha(colors[i], 110));
			g.draw(shape);
			g.setFont(Theme.title());
			FontMetrics bold = g.getFontMetrics();
			String value = items[i][0];
			Ui.shadowed(g, value, Math.round(cx + (cell - bold.stringWidth(value)) / 2), y + bold.getAscent() + 1, colors[i]);
			g.setFont(Theme.small());
			g.setColor(Theme.TEXT_MUTED);
			String label = items[i][1];
			g.drawString(label, Math.round(cx + (cell - small.stringWidth(label)) / 2), y + h - 4);
		}
		return y + h;
	}

	private static void centered(Graphics2D g, String text, int x, int w, int baseline, Color color)
	{
		FontMetrics fm = g.getFontMetrics();
		Ui.shadowed(g, text, x + (w - fm.stringWidth(text)) / 2, baseline, color);
	}

	/** A gilt line ending in a diamond, either side of the year. */
	private static void ornament(Graphics2D g, int from, int to, int y)
	{
		if (to - from < 12)
		{
			return;
		}
		boolean towardRight = from < WIDTH / 2;
		g.setStroke(new BasicStroke(1f));
		g.setPaint(new GradientPaint(from, 0, Theme.alpha(Theme.GOLD, towardRight ? 0 : 170), to, 0, Theme.alpha(Theme.GOLD, towardRight ? 170 : 0)));
		g.drawLine(from, y, to, y);
		diamond(g, towardRight ? to : from, y, 3, Theme.GOLD);
	}

	private static void header(Graphics2D g, String text, String trailing, int x, int y, int w)
	{
		g.setFont(Theme.small());
		SectionHeader.paint(g, text.toUpperCase(), trailing, x, y, w, 20);
	}

	private static void rule(Graphics2D g, int x, int y, int w)
	{
		g.setStroke(new BasicStroke(1f));
		g.setPaint(new GradientPaint(x, 0, Theme.alpha(Theme.GOLD, 0), x + w / 2f, 0, Theme.alpha(Theme.GOLD, 150), true));
		g.drawLine(x, y, x + w, y);
		diamond(g, x + w / 2f, y, 3, Theme.GOLD);
	}

	private static void diamond(Graphics2D g, float cx, float cy, float r, Color color)
	{
		Path2D d = new Path2D.Float();
		d.moveTo(cx, cy - r);
		d.lineTo(cx + r, cy);
		d.lineTo(cx, cy + r);
		d.lineTo(cx - r, cy);
		d.closePath();
		g.setColor(color);
		g.fill(d);
	}
}

package com.codex.annals.ui;

import com.codex.annals.core.Entry;
import com.codex.annals.core.Recap;
import java.awt.BorderLayout;
import java.awt.GridLayout;
import java.time.Instant;
import java.time.ZoneId;
import java.util.List;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;

/** The Year tab: one year told in full, from its headline down to the records it set. */
final class YearView
{
	private static final int SKILLS = 6;
	private static final int BOSSES = 6;

	private YearView()
	{
	}

	/**
	 * @param years the year chooser, or null when only one year is kept
	 * @param currentMonth the month still being lived when this is the current year, or -1
	 */
	static JComponent build(Recap r, Segmented years, int currentMonth, ZoneId zone, ItemIcons items, Icons icons, Runnable onLoaded)
	{
		StackPanel stack = new StackPanel(8, 8);
		if (years != null)
		{
			stack.add(years);
		}
		if (r == null)
		{
			stack.add(Views.note("No year yet", "Your year begins the first time you log in with Codex Annals on. Everything you do after that is counted here."));
			return stack;
		}

		Card hero = new Card(new BorderLayout());
		hero.highlighted(true);
		JPanel lines = new JPanel();
		lines.setOpaque(false);
		lines.setLayout(new BoxLayout(lines, BoxLayout.Y_AXIS));
		JLabel year = Ui.label(String.valueOf(r.getYear()), Theme.title().deriveFont(Theme.title().getSize2D() * 2), Theme.GOLD_BRIGHT);
		lines.add(year);
		lines.add(Ui.label(r.getHeadline(), Theme.body(), Theme.TEXT));
		lines.add(Ui.label(Format.hours(r.getPlayedMs()) + " across " + Format.plural(r.getDaysPlayed(), "day", "days"), Theme.small(), Theme.TEXT_MUTED));
		hero.add(lines, BorderLayout.CENTER);
		stack.add(hero);

		JPanel tiles = new JPanel(new GridLayout(2, 2, 6, 6));
		tiles.setOpaque(false);
		tiles.add(new StatTile(Format.number(r.getDaysPlayed()), "Days played",
			r.getLongestStreak() > 1 ? r.getLongestStreak() + " in a row" : "", Theme.TEAL));
		tiles.add(new StatTile("+" + Format.number(r.getLevelsGained()), "Levels", Format.xp(r.getXpGained()) + " xp", Theme.GREEN));
		tiles.add(new StatTile(Format.number(r.getCollection()), "Log slots", r.getPets() > 0 ? Format.plural(r.getPets(), "pet", "pets") : "new this year", Theme.GOLD));
		tiles.add(new StatTile(Format.number(r.getQuests()), "Quests", Format.plural(r.getDiaries(), "diary", "diaries"), Theme.FEAT));
		stack.add(tiles);

		int busiest = r.busiestMonth();
		stack.add(new SectionHeader("Months", busiest >= 0 ? "busiest " + Format.monthName(busiest) : null));
		stack.add(new MonthStrip(r.getMonthDays(), r.getMonthEntries(), currentMonth));

		List<Recap.SkillYear> skills = r.getSkills();
		if (!skills.isEmpty())
		{
			stack.add(new SectionHeader("Skills", skills.size() > SKILLS ? skills.size() + " trained" : null));
			long top = skills.get(0).getGained();
			for (int i = 0; i < skills.size() && i < SKILLS; i++)
			{
				Recap.SkillYear s = skills.get(i);
				stack.add(new SkillYearRow(s, icons == null ? null : icons.skill(s.getSkill()), s.getGained() / (double) top));
			}
		}

		List<Recap.KillYear> bosses = r.getBosses();
		if (!bosses.isEmpty())
		{
			stack.add(new SectionHeader("Bosses", Format.plural(r.getKills(), "kill", "kills")));
			int top = bosses.get(0).getKills();
			for (int i = 0; i < bosses.size() && i < BOSSES; i++)
			{
				stack.add(new KillYearRow(bosses.get(i), bosses.get(i).getKills() / (double) top));
			}
		}

		List<Entry> highlights = r.getHighlights();
		if (!highlights.isEmpty())
		{
			stack.add(new SectionHeader("Highlights"));
			JPanel run = new JPanel();
			run.setOpaque(false);
			run.setLayout(new BoxLayout(run, BoxLayout.Y_AXIS));
			for (int i = 0; i < highlights.size(); i++)
			{
				Entry e = highlights.get(i);
				EntryRow row = new EntryRow(e, Instant.ofEpochMilli(e.getAt()).atZone(zone).toLocalDate(), Views.icon(e, items, icons, onLoaded),
					i == 0, i == highlights.size() - 1);
				row.setAlignmentX(JComponent.LEFT_ALIGNMENT);
				run.add(row);
			}
			stack.add(run);
		}

		stack.add(new SectionHeader("Records"));
		Card records = new Card(new GridLayout(0, 1, 0, 3));
		records.add(record("Longest streak", Format.plural(r.getLongestStreak(), "day", "days")));
		records.add(record("Busiest month", busiest >= 0 ? Format.monthName(busiest) + ", " + Format.plural(r.getMonthDays()[busiest], "day", "days") : "-"));
		Entry drop = r.getBiggestDrop();
		records.add(record("Biggest drop", drop == null ? "-" : Format.coins(drop.getValue())));
		if (drop != null)
		{
			records.add(Ui.label(drop.getTitle(), Theme.small(), Theme.GOLD));
		}
		records.add(record("Clue scrolls", Format.number(r.getClues())));
		records.add(record("Combat tasks", Format.number(r.getTasks())));
		stack.add(records);
		return stack;
	}

	private static JPanel record(String label, String value)
	{
		JPanel line = new JPanel(new BorderLayout());
		line.setOpaque(false);
		line.add(Ui.label(label, Theme.small(), Theme.TEXT_MUTED), BorderLayout.WEST);
		line.add(Ui.label(value, Theme.small(), Theme.TEXT), BorderLayout.EAST);
		return line;
	}
}

package com.codex.annals.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.time.ZonedDateTime;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class AnnalsTest
{
	static final ZoneId UTC = ZoneOffset.UTC;

	static long at(int year, int month, int day, int hour)
	{
		return ZonedDateTime.of(year, month, day, hour, 0, 0, 0, UTC).toInstant().toEpochMilli();
	}

	static Annals begun(long now, int slayer, long slayerXp)
	{
		Map<String, Long> xp = new LinkedHashMap<>();
		Map<String, Integer> levels = new LinkedHashMap<>();
		xp.put("Slayer", slayerXp);
		levels.put("Slayer", slayer);
		xp.put("Mining", 1_000_000L);
		levels.put("Mining", 70);
		Annals annals = new Annals();
		annals.begin(now, UTC, "Zezima", new Baseline(now, slayer + 70, slayerXp + 1_000_000L, 100, 200, 150, 170, Collections.emptyList()),
			xp, levels, 100);
		return annals;
	}

	@Test
	public void beginsOnce()
	{
		long now = at(2026, 3, 12, 10);
		Annals annals = begun(now, 80, 2_000_000L);
		assertTrue(annals.isBegun());
		assertEquals(1, annals.getEntries().size());
		assertEquals(Entry.Kind.BEGIN, annals.getEntries().get(0).getKind());
		List<Entry> again = annals.begin(now + 1000, UTC, "Zezima", annals.getBaseline(), Collections.emptyMap(), Collections.emptyMap(), 100);
		assertTrue(again.isEmpty());
		assertEquals(now, annals.getBegunAt());
	}

	@Test
	public void writesLevelsAnd99s()
	{
		long now = at(2026, 3, 12, 10);
		Annals annals = begun(now, 98, 12_000_000L);
		List<Entry> written = annals.stat("Slayer", 13_034_431L, 99, now + 60_000, UTC, true);
		assertEquals(Entry.Kind.MAX, written.get(0).getKind());
		assertEquals("99 Slayer", written.get(0).getTitle());
		assertEquals("Your first 99", written.get(0).getDetail());

		written = annals.stat("Mining", 1_100_000L, 71, now + 120_000, UTC, true);
		assertEquals("Mining 71", written.get(0).getTitle());

		// Only round numbers when every level is not wanted.
		assertTrue(annals.stat("Mining", 1_200_000L, 72, now + 180_000, UTC, false).isEmpty());
	}

	@Test
	public void writesTotalAndExperienceMilestones()
	{
		long now = at(2026, 3, 12, 10);
		Annals annals = begun(now, 29, 49_990_000L);
		List<Entry> written = annals.stat("Slayer", 50_010_000L, 30, now + 1, UTC, true);
		boolean total = false;
		boolean xp = false;
		for (Entry e : written)
		{
			total |= e.getTitle().equals("Total level 100");
			xp |= e.getTitle().equals("50M Slayer");
		}
		// 30 + 70 = 100 is under the 500 floor for total milestones.
		assertTrue(!total);
		assertTrue(xp);
		// The account total was already past 50M, so only the skill crossed a mark.
		assertEquals(1, written.size() - 1);
	}

	@Test
	public void countsKillsAndKeepsMilestones()
	{
		long now = at(2026, 5, 1, 10);
		Annals annals = begun(now, 80, 2_000_000L);
		Entry first = annals.killCount("Vorkath", 1, now, UTC);
		assertEquals("First Vorkath", first.getTitle());
		for (int kc = 2; kc < 50; kc++)
		{
			assertNull(annals.killCount("Vorkath", kc, now, UTC));
		}
		Entry fifty = annals.killCount("Vorkath", 50, now, UTC);
		assertEquals("Vorkath 50", fifty.getTitle());
		assertEquals(50, (int) annals.getYear(2026).getKills().get("Vorkath"));
		// The same count twice is one kill, not two.
		annals.killCount("Vorkath", 50, now, UTC);
		assertEquals(50, (int) annals.getYear(2026).getKills().get("Vorkath"));
	}

	@Test
	public void startsANewYearFromTheLastReadings()
	{
		long now = at(2026, 12, 31, 23);
		Annals annals = begun(now, 80, 2_000_000L);
		annals.stat("Slayer", 2_500_000L, 81, now + 1000, UTC, true);
		long next = at(2027, 1, 1, 0) + 5000;
		annals.stat("Slayer", 2_600_000L, 81, next, UTC, true);
		Year y2027 = annals.getYear(2027);
		assertNotNull(y2027);
		assertEquals(100_000L, y2027.gained("Slayer"));
		assertEquals(500_000L, annals.getYear(2026).gained("Slayer"));
	}

	@Test
	public void keepsPlayTimeAndDays()
	{
		long now = at(2026, 6, 1, 10);
		Annals annals = begun(now, 80, 2_000_000L);
		for (int i = 0; i < 100; i++)
		{
			annals.tick(now + i * 600L, 600, UTC);
		}
		annals.tick(at(2026, 6, 2, 10), 600, UTC);
		Year y = annals.getYear(2026);
		assertEquals(101 * 600L, y.getPlayedMs());
		assertEquals(2, y.getDays().size());
	}

	@Test
	public void compactsOrdinaryLevelsFirst()
	{
		long now = at(2026, 1, 1, 10);
		Annals annals = begun(now, 1, 0L);
		annals.record(new Entry(Entry.Kind.PET, now, "A pet followed you home", null), now, UTC);
		long xp = 0;
		for (int i = 0; i < Annals.MAX_ENTRIES + 50; i++)
		{
			annals.stat("Slayer", ++xp, 2 + i % 90, now + i, UTC, true);
			annals.levels.put("Slayer", 1);
		}
		assertEquals(Annals.MAX_ENTRIES, annals.getEntries().size());
		assertEquals(Entry.Kind.BEGIN, annals.getEntries().get(0).getKind());
		assertEquals(Entry.Kind.PET, annals.getEntries().get(1).getKind());
	}

	@Test
	public void clueCountsEveryOneButKeepsMilestones()
	{
		long now = at(2026, 1, 1, 10);
		Annals annals = begun(now, 80, 2_000_000L);
		assertNull(annals.record(ChatParser.entry("You have completed 12 hard Treasure Trails.", now, null), now, UTC));
		assertNotNull(annals.record(ChatParser.entry("You have completed 25 hard Treasure Trails.", now, null), now, UTC));
		assertEquals(2, annals.getYear(2026).getClues());
	}

	@Test
	public void milestonesOfTotalExperience()
	{
		assertEquals(100_000_000L, Annals.totalXpMilestone(99_000_000L, 101_000_000L));
		assertEquals(1_500_000_000L, Annals.totalXpMilestone(1_499_000_000L, 1_500_100_000L));
		assertEquals(0, Annals.totalXpMilestone(101_000_000L, 102_000_000L));
		assertEquals("1.5B", Annals.shortAmount(1_500_000_000L));
	}

	@Test
	public void aDropThatFillsALogSlotIsOneLine()
	{
		long now = at(2026, 7, 21, 20);
		Annals annals = begun(now, 80, 2_000_000L);
		annals.record(ChatParser.entry("New item added to your collection log: Elder maul", now, null), now, UTC);
		Entry merged = annals.drop("Elder maul", 1, 21003, 112_000_000L, "Chambers of Xeric", now + 2000);
		assertEquals(Entry.Kind.COLLECTION, merged.getKind());
		assertEquals("New log slot from Chambers of Xeric", merged.getDetail());
		assertEquals(2, annals.getEntries().size());

		annals.drop("Dragon warhammer", 1, 13576, 31_000_000L, "Lizardman shaman", now + 60_000);
		Entry slot = annals.record(ChatParser.entry("New item added to your collection log: Dragon warhammer", now + 61_000, null), now + 61_000, UTC);
		assertEquals(Entry.Kind.COLLECTION, slot.getKind());
		assertEquals(31_000_000L, slot.getValue());
		assertEquals(3, annals.getEntries().size());
		assertEquals("Elder maul", Recap.of(annals, 2026, UTC).getBiggestDrop().getTitle());
	}
}

package com.codex.annals.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class ChatParserTest
{
	@Test
	public void readsKillCounts()
	{
		ChatParser.KillCount kc = ChatParser.killCount("Your Vorkath kill count is: 1,412.");
		assertEquals("Vorkath", kc.getName());
		assertEquals(1412, kc.getCount());

		kc = ChatParser.killCount("Your completed Theatre of Blood count is: 25.");
		assertEquals("Theatre of Blood", kc.getName());

		kc = ChatParser.killCount("Your Barrows chest count is: 300.");
		assertEquals("Barrows chest", kc.getName());

		assertNull(ChatParser.killCount("You have a funny feeling like you're being followed."));
	}

	@Test
	public void readsEntries()
	{
		Entry e = ChatParser.entry("New item added to your collection log: Draconic visage", 1, null);
		assertEquals(Entry.Kind.COLLECTION, e.getKind());
		assertEquals("Draconic visage", e.getTitle());

		e = ChatParser.entry("You have a funny feeling like you're being followed.", 1, "Vorkath");
		assertEquals(Entry.Kind.PET, e.getKind());
		assertEquals("While killing Vorkath", e.getDetail());

		e = ChatParser.entry("Congratulations, you've completed a quest: Dragon Slayer II", 1, null);
		assertEquals(Entry.Kind.QUEST, e.getKind());
		assertEquals("Dragon Slayer II", e.getTitle());

		e = ChatParser.entry("Congratulations! You have completed all of the hard tasks in the Varrock area. Speak to Toby to claim your reward.", 1, null);
		assertEquals(Entry.Kind.DIARY, e.getKind());
		assertEquals("Varrock hard diary", e.getTitle());

		e = ChatParser.entry("Congratulations, you've completed an elite combat task: Faithless Crypt Run (5 points).", 1, null);
		assertEquals(Entry.Kind.TASK, e.getKind());
		assertEquals("Faithless Crypt Run", e.getTitle());
		assertEquals("Elite combat task", e.getDetail());

		e = ChatParser.entry("You have completed 100 medium Treasure Trails.", 1, null);
		assertEquals(Entry.Kind.CLUE, e.getKind());
		assertEquals("Medium clue number 100", e.getTitle());

		assertNull(ChatParser.entry("Welcome to Old School RuneScape.", 1, null));
	}

	@Test
	public void clueMilestones()
	{
		assertTrue(ChatParser.clueMilestone(1));
		assertTrue(ChatParser.clueMilestone(25));
		assertTrue(ChatParser.clueMilestone(300));
		assertFalse(ChatParser.clueMilestone(12));
		assertFalse(ChatParser.clueMilestone(150));
	}
}

package com.codex.annals.core;

import static org.junit.Assert.assertEquals;
import java.util.Arrays;
import org.junit.Test;

public class RecapTest
{
	@Test
	public void tellsTheYear()
	{
		long now = AnnalsTest.at(2026, 3, 12, 10);
		Annals annals = AnnalsTest.begun(now, 98, 12_000_000L);
		annals.tick(now, 600, AnnalsTest.UTC);
		annals.tick(AnnalsTest.at(2026, 3, 13, 10), 600, AnnalsTest.UTC);
		annals.tick(AnnalsTest.at(2026, 3, 14, 10), 600, AnnalsTest.UTC);
		annals.tick(AnnalsTest.at(2026, 7, 1, 10), 600, AnnalsTest.UTC);
		annals.stat("Slayer", 13_100_000L, 99, AnnalsTest.at(2026, 7, 1, 11), AnnalsTest.UTC, true);
		annals.killCount("Vorkath", 1, AnnalsTest.at(2026, 7, 1, 12), AnnalsTest.UTC);
		annals.drop("Draconic visage", 1, 11286, 3_000_000L, "Vorkath", AnnalsTest.at(2026, 7, 1, 12));

		Recap r = Recap.of(annals, 2026, AnnalsTest.UTC);
		assertEquals("The year of 99 Slayer", r.getHeadline());
		assertEquals(4, r.getDaysPlayed());
		assertEquals(3, r.getLongestStreak());
		assertEquals(2, r.busiestMonth());
		assertEquals(1, r.getLevelsGained());
		assertEquals(1_100_000L, r.getXpGained());
		assertEquals("Slayer", r.getSkills().get(0).getSkill());
		assertEquals("Draconic visage", r.getBiggestDrop().getTitle());
		assertEquals(Entry.Kind.MAX, r.getHighlights().get(0).getKind());
		assertEquals(Arrays.asList(2026), Recap.years(annals));
	}
}

package com.codex.annals.core;

import static org.junit.Assert.assertEquals;
import java.util.List;
import org.junit.Test;

public class TimelineTest
{
	@Test
	public void foldsADayOfLevels()
	{
		long now = AnnalsTest.at(2026, 3, 12, 10);
		Annals annals = AnnalsTest.begun(now, 60, 300_000L);
		annals.stat("Slayer", 340_000L, 61, now + 1000, AnnalsTest.UTC, true);
		annals.stat("Slayer", 380_000L, 62, now + 2000, AnnalsTest.UTC, true);
		annals.stat("Slayer", 430_000L, 63, now + 3000, AnnalsTest.UTC, true);
		annals.record(new Entry(Entry.Kind.QUEST, now + 4000, "Dragon Slayer II", "Quest complete"), now, AnnalsTest.UTC);
		annals.stat("Mining", 1_100_000L, 71, now + 5000, AnnalsTest.UTC, true);
		annals.stat("Slayer", 480_000L, 64, now + 6000, AnnalsTest.UTC, true);

		List<Timeline.Row> rows = Timeline.rows(annals.getEntries(), Entry.Chapter.ALL, AnnalsTest.UTC);
		// Newest first: Mining + Slayer folded, the quest, three Slayer levels folded, the opening.
		assertEquals(4, rows.size());
		assertEquals("2 levels", rows.get(0).getEntry().getTitle());
		assertEquals("Slayer 64, Mining 71", rows.get(0).getEntry().getDetail());
		assertEquals("Dragon Slayer II", rows.get(1).getEntry().getTitle());
		assertEquals("Slayer 60 to 63", rows.get(2).getEntry().getTitle());
		assertEquals(3, rows.get(2).getFolded());

		List<Timeline.Row> feats = Timeline.rows(annals.getEntries(), Entry.Chapter.FEATS, AnnalsTest.UTC);
		assertEquals(1, feats.size());
	}
}
